const moveGeoAnswer = (question, target, reforge = false) => {
  const item = reforge ? question.reforge : question;
  const current = item.correct;
  if (current !== target) [item.options[current], item.options[target]] = [item.options[target], item.options[current]];
  item.correct = target;
};
