BANKS["GCSE-HIST-AMERICA"].questions.push(
  gcseHistoryQuestion("GCSE-HIST-AM-21","GCSE-HIST-AMERICA","Why did radio and cinema matter to American society in the 1920s?",{A:"They spread shared entertainment and consumer messages",B:"They ended advertising",C:"They were available only in rural areas",D:"They replaced all newspapers"},"A","Mass media created national celebrities, spread popular culture and gave advertisers new ways to encourage consumption.",{stem:"What did jazz symbolise to many young Americans?",options:{A:"A return to Victorian values",B:"Modern culture and changing social attitudes",C:"The end of urban life",D:"Support for prohibition"},correct:"B"}),
  gcseHistoryQuestion("GCSE-HIST-AM-22","GCSE-HIST-AMERICA","What was one effect of the Nineteenth Amendment?",{A:"Women gained the federal vote",B:"Women were banned from factories",C:"Prohibition ended",D:"The Supreme Court was abolished"},"A","The amendment gave women the constitutional right to vote, although discrimination and unequal access continued in practice.",{stem:"Why did the flapper challenge some traditional attitudes?",options:{A:"She represented new fashions and independence",B:"She opposed all paid work",C:"She supported racial segregation",D:"She campaigned to restore monarchy"},correct:"A"}),
  gcseHistoryQuestion("GCSE-HIST-AM-23","GCSE-HIST-AMERICA","Why did many African-Americans move north during the Great Migration?",{A:"To find industrial work and escape southern racism",B:"To join the Confederate army",C:"To avoid all factory employment",D:"Because Congress required relocation"},"A","Industrial jobs and the search for safety drew many African-Americans north, although discrimination and segregation remained there too.",{stem:"What did the Great Migration help create in northern cities?",options:{A:"Larger African-American communities",B:"The end of racial tension",C:"A rural population boom",D:"The closure of factories"},correct:"A"}),
  gcseHistoryQuestion("GCSE-HIST-AM-24","GCSE-HIST-AMERICA","Why did the New Deal not end racial inequality?",{A:"Many programmes were administered locally and discriminated",B:"Roosevelt abolished civil rights laws",C:"African-Americans received every benefit first",D:"The Supreme Court ended segregation"},"A","Some New Deal measures excluded agricultural and domestic workers or were administered in ways that disadvantaged African-Americans.",{stem:"What was a limitation of the New Deal for women?",options:{A:"It guaranteed equal pay",B:"Many programmes prioritised male breadwinners",C:"It banned women from voting",D:"It ended women's employment"},correct:"B"}),
  gcseHistoryQuestion("GCSE-HIST-AM-25","GCSE-HIST-AMERICA","What did the Fair Deal attempt to do after 1945?",{A:"Extend social and economic reforms",B:"Restore prohibition",C:"End federal responsibility",D:"Support McCarthy's investigations"},"A","Truman's Fair Deal proposed expanding welfare and civil rights, although Congress blocked or limited many measures.",{stem:"Why was the GI Bill important after the Second World War?",options:{A:"It helped veterans access education and housing",B:"It restricted veterans from work",C:"It ended television",D:"It created the KKK"},correct:"A"}),
  gcseHistoryQuestion("GCSE-HIST-AM-26","GCSE-HIST-AMERICA","Why did suburbanisation grow in post-war America?",{A:"Cars, mortgages and new housing encouraged movement",B:"Cities banned all families",C:"The government ended road building",D:"Factories moved overseas immediately"},"A","Mass car ownership, highway construction and affordable mortgages supported movement to suburbs, though racial exclusion was common.",{stem:"How could suburban growth reinforce inequality?",options:{A:"All groups gained identical access",B:"Housing discrimination excluded many Black families",C:"It ended segregation in cities",D:"It stopped consumerism"},correct:"B"}),
  gcseHistoryQuestion("GCSE-HIST-AM-27","GCSE-HIST-AMERICA","Why did the Montgomery Bus Boycott succeed?",{A:"It used sustained organisation and economic pressure",B:"The Supreme Court ordered it on day one",C:"Bus companies supported segregation",D:"It lasted only one afternoon"},"A","The boycott lasted over a year and combined local organisation, car pools and financial pressure with legal action.",{stem:"What immediate issue triggered the Montgomery boycott?",options:{A:"Rosa Parks's arrest",B:"The Wall Street Crash",C:"The Cuban Missile Crisis",D:"The New Deal"},correct:"A"}),
  gcseHistoryQuestion("GCSE-HIST-AM-28","GCSE-HIST-AMERICA","What did the Freedom Rides aim to test?",{A:"Whether interstate bus segregation rules were enforced",B:"Whether women could vote",C:"Whether prohibition had ended",D:"Whether the New Deal funded schools"},"A","Black and white activists travelled together to challenge segregation in interstate bus facilities.",{stem:"Why did Freedom Riders attract national attention?",options:{A:"Violence was shown in the media",B:"They received no opposition",C:"They travelled only abroad",D:"They supported segregation"},correct:"A"}),
  gcseHistoryQuestion("GCSE-HIST-AM-29","GCSE-HIST-AMERICA","Why did the Great Society have mixed results?",{A:"It reduced some poverty but could not remove structural inequality",B:"It provided no social programmes",C:"It ended after one month",D:"It focused only on foreign policy"},"A","Medicare, Medicaid and anti-poverty programmes improved access for many, but poverty, racial inequality and opposition limited their impact.",{stem:"What was one Great Society achievement?",options:{A:"Medicare for older Americans",B:"A return to segregation",C:"The abolition of schools",D:"The end of all poverty"},correct:"A"}),
  gcseHistoryQuestion("GCSE-HIST-AM-30","GCSE-HIST-AMERICA","What did Roe v Wade decide in 1973?",{A:"The Constitution protected a right to abortion in certain circumstances",B:"Women could not work",C:"Segregation was constitutional",D:"The New Deal had ended"},"A","The Supreme Court ruling recognised a constitutional privacy right that limited state abortion bans, though it remained controversial.",{stem:"Why did Roe v Wade become a major political controversy?",options:{A:"It affected competing views about rights and state power",B:"It ended the Civil Rights Movement",C:"It created the Federal Reserve",D:"It decided a presidential election"},correct:"A"})
);
BANKS["GCSE-HIST-INTERWAR"].questions.push(
  gcseHistoryQuestion("GCSE-HIST-IW-21","GCSE-HIST-INTERWAR","Why did the Treaty of Versailles create problems for new states?",{A:"Borders left minorities and territorial disputes",B:"It gave every group its own state",C:"It abolished nationalism",D:"It made all borders temporary"},"A","Self-determination could not be applied consistently, leaving minorities outside their preferred state and creating grievances.",{stem:"What was one result of redrawing eastern European borders?",options:{A:"New minorities lived inside several states",B:"All disputes disappeared",C:"Germany gained every colony",D:"The League gained an army"},correct:"A"}),
  gcseHistoryQuestion("GCSE-HIST-IW-22","GCSE-HIST-INTERWAR","Why did the League's agencies count as a strength?",{A:"They achieved practical work in health and refugees",B:"They commanded large armies",C:"They ended all poverty",D:"They controlled every government"},"A","Agencies such as the Health Organisation and Refugee Organisation achieved useful cooperation even when political action failed.",{stem:"What limited the League's agencies?",options:{A:"They depended on member cooperation and funding",B:"They were controlled by Germany",C:"They had no practical purpose",D:"They were created in 1939"},correct:"A"}),
  gcseHistoryQuestion("GCSE-HIST-IW-23","GCSE-HIST-INTERWAR","Why did Britain and France hesitate to confront Italy over Abyssinia?",{A:"They feared pushing Mussolini towards Hitler",B:"They wanted Italy to conquer Britain",C:"They had no interest in Europe",D:"They supported the League's military force"},"A","British and French leaders wanted Italian support against Germany, so they prioritised diplomacy over decisive sanctions.",{stem:"What was the consequence of the Abyssinian crisis for collective security?",options:{A:"Aggressors saw that League opposition could be resisted",B:"The League became militarily stronger",C:"Italy left fascism",D:"Germany withdrew from Europe"},correct:"A"}),
  gcseHistoryQuestion("GCSE-HIST-IW-24","GCSE-HIST-INTERWAR","Why did Hitler withdraw Germany from the League in 1933?",{A:"He rejected international restrictions and cooperation",B:"He wanted to join the League later",C:"The League had invaded Germany",D:"France demanded German membership"},"A","Withdrawal allowed Hitler to reject collective security while pursuing rearmament and revision of Versailles.",{stem:"How did German rearmament challenge Versailles?",options:{A:"It broke military restrictions",B:"It reduced Germany's army",C:"It strengthened the League",D:"It returned colonies to Britain"},correct:"A"}),
  gcseHistoryQuestion("GCSE-HIST-IW-25","GCSE-HIST-INTERWAR","Why did Hitler believe Britain and France might not resist expansion?",{A:"Their weak responses to earlier treaty breaches encouraged him",B:"They had declared support for invasion",C:"They had no armed forces at all",D:"The League had already surrendered"},"A","The lack of decisive action over the Rhineland, Anschluss and Munich encouraged Hitler to believe opponents lacked the will to fight.",{stem:"Which earlier crisis most clearly tested Allied resolve before Munich?",options:{A:"The remilitarisation of the Rhineland",B:"The Aaland Islands",C:"The Dawes Plan",D:"The Kellogg-Briand signing"},correct:"A"}),
  gcseHistoryQuestion("GCSE-HIST-IW-26","GCSE-HIST-INTERWAR","Why did the Munich Agreement fail to secure lasting peace?",{A:"It rewarded pressure and left Czechoslovakia vulnerable",B:"It removed all German ambitions",C:"It gave the League an army",D:"It made Poland a German ally"},"A","Munich transferred the Sudetenland but did not satisfy Hitler's wider ambitions; Germany occupied the rest of Czechoslovakia in 1939.",{stem:"What did the occupation of Prague in March 1939 change?",options:{A:"It undermined the claim that Hitler only wanted German-speaking lands",B:"It ended German expansion",C:"It restored the League",D:"It made appeasement more popular"},correct:"A"}),
  gcseHistoryQuestion("GCSE-HIST-IW-27","GCSE-HIST-INTERWAR","Why did Poland reject Hitler's demand for Danzig?",{A:"It feared loss of sovereignty and further German demands",B:"It wanted to join the USSR",C:"It had no access to the Baltic",D:"Britain had invaded Poland"},"A","Danzig and the Polish Corridor had strategic and symbolic importance, while Poland feared surrender would invite further demands.",{stem:"What did the British guarantee to Poland aim to do?",options:{A:"Deter German attack",B:"Support the Nazi-Soviet Pact",C:"End Polish independence",D:"Give Danzig to Germany"},correct:"A"}),
  gcseHistoryQuestion("GCSE-HIST-IW-28","GCSE-HIST-INTERWAR","Why did the Soviet Union sign the Nazi-Soviet Pact?",{A:"It bought time and offered territorial gains",B:"It accepted Nazi ideology",C:"It wanted Britain to rule Poland",D:"It ended Soviet communism"},"A","Stalin gained time to prepare and expected territorial concessions in eastern Europe, including a division of Poland.",{stem:"What did the pact's secret protocol do?",options:{A:"Divided spheres of influence in eastern Europe",B:"Created NATO",C:"Guaranteed French security",D:"Ended German rearmament"},correct:"A"}),
  gcseHistoryQuestion("GCSE-HIST-IW-29","GCSE-HIST-INTERWAR","Why did the failure of collective security contribute to war?",{A:"Aggressors were not consistently deterred",B:"It made every state pacifist",C:"It ended nationalism",D:"It prevented rearmament"},"A","Repeated failures in Manchuria, Abyssinia and Europe undermined confidence that international cooperation could restrain aggression.",{stem:"What is collective security intended to mean?",options:{A:"States act together against aggression",B:"Each state fights alone",C:"Only dictators enforce peace",D:"Trade replaces diplomacy"},correct:"A"}),
  gcseHistoryQuestion("GCSE-HIST-IW-30","GCSE-HIST-INTERWAR","Which factor best explains why war broke out in 1939 rather than earlier?",{A:"Hitler's risks increased as appeasement delayed confrontation",B:"Germany had abandoned expansion",C:"The League had defeated Japan",D:"Poland invited invasion"},"A","Appeasement postponed direct conflict while allowing German strength and ambitions to grow; the invasion of Poland finally triggered declarations of war.",{stem:"What immediate promise did Britain make to Poland in 1939?",options:{A:"To support Poland if attacked",B:"To cede Danzig",C:"To join the Nazi-Soviet Pact",D:"To leave Europe permanently"},correct:"A"})
);
for (const [bankId, [basePlan, reforgePlan]] of Object.entries({
  "GCSE-HIST-AMERICA":["ABCDABCDAB","CADBBCADDB"],
  "GCSE-HIST-INTERWAR":["CDABCDABCD","DBACCADBAC"]
})) {
  const added = BANKS[bankId].questions.slice(-10);
  added.forEach((question, index) => { moveGcseHistoryAnswer(question, basePlan[index]); moveGcseHistoryAnswer(question, reforgePlan[index], true); });
  for (const question of added) for (const item of [question, question.reforge]) {
    const lengths = Object.fromEntries(Object.entries(item.options).map(([letter, option]) => [letter, option.length]));
    const max = Math.max(...Object.values(lengths));
    if (lengths[item.correct] !== max || Object.values(lengths).filter(length => length === max).length !== 1) continue;
    const alternative = Object.keys(item.options).filter(letter => letter !== item.correct).sort((a, b) => lengths[b] - lengths[a])[0];
    while (item.options[alternative].length <= item.options[item.correct].length) item.options[alternative] += " (in context)";
  }
}


// ===== GCSE COMBINED SCIENCE 1SC0: FIRST THREE PAPERS =====
// These banks follow Pearson's Paper 1 Biology, Paper 2 Chemistry and Paper 3
// Physics content. Questions are original, with separate Reforge prompts and
// independently balanced answer positions.
const gcseScienceQuestion = (id, spec, stem, options, correct, scaffold, tag, reforge) => ({
  id, spec, stem, options, correct, tag, scaffold,
  reforge: { stem: reforge.stem, options: reforge.options, correct: reforge.correct }
});

BANKS["GCSE-SCI-BIO-1"] = {
  label: "Biology 1 — Cells, Genetics, Selection & Disease",
  color: "#166534",
  questions: [
    gcseScienceQuestion("SCI-BIO1-01", "1SC0 Topic 1", "Which feature is present in both prokaryotic and eukaryotic cells?", {A:"A cell membrane",B:"A nucleus",C:"Mitochondria",D:"Chloroplasts"}, "A", "Both cell types have a cell membrane, cytoplasm, ribosomes and genetic material. Prokaryotes do not have a nucleus or membrane-bound organelles.", "BIO-CELL-01", {stem:"Which structure controls movement into and out of a cell?",options:{A:"Cell wall",B:"Cell membrane",C:"Cytoplasm",D:"Ribosome"},correct:"B"}),
    gcseScienceQuestion("SCI-BIO1-02", "1SC0 Topic 1", "A microscope has a 10× eyepiece and a 40× objective lens. What is its total magnification?", {A:"4×",B:"40×",C:"400×",D:"4,000×"}, "C", "Total magnification is calculated by multiplying the eyepiece magnification by the objective magnification: 10 × 40 = 400×.", "BIO-MICRO-01", {stem:"An image is 30 mm long at 150× magnification. What is its actual length?",options:{A:"0.02 mm",B:"0.2 mm",C:"4.5 mm",D:"180 mm"},correct:"A"}),
    gcseScienceQuestion("SCI-BIO1-03", "1SC0 Topic 2", "What is the main role of ribosomes in a cell?", {A:"Releasing energy",B:"Making proteins",C:"Controlling osmosis",D:"Storing genetic material"}, "B", "Ribosomes are the sites of protein synthesis. Mitochondria release energy, while the nucleus contains most of the genetic material.", "BIO-CELL-02", {stem:"Which structure is the main site of aerobic respiration?",options:{A:"Nucleus",B:"Ribosome",C:"Mitochondrion",D:"Cell wall"},correct:"C"}),
    gcseScienceQuestion("SCI-BIO1-04", "1SC0 Topic 2", "Why does mitosis produce two genetically identical daughter cells?", {A:"DNA is copied once before one division",B:"Each cell receives different genes",C:"The chromosome number is halved",D:"The cells combine after division"}, "A", "Before mitosis, DNA is replicated. The copied chromosomes are then separated so each daughter cell receives an identical set.", "BIO-MITOSIS-01", {stem:"What is one function of mitosis in a multicellular organism?",options:{A:"Producing gametes",B:"Reducing chromosome number",C:"Creating genetic variation",D:"Growth and tissue repair"},correct:"D"}),
    gcseScienceQuestion("SCI-BIO1-05", "1SC0 Topic 3", "What is meant by the term allele?", {A:"A type of cell division",B:"A version of a gene",C:"A complete chromosome set",D:"A visible characteristic"}, "B", "An allele is an alternative form of a gene. Different alleles can contribute to variation in an inherited characteristic.", "BIO-GEN-01", {stem:"What is the term for an organism's observable characteristic?",options:{A:"Phenotype",B:"Genotype",C:"Allele",D:"Gamete"},correct:"A"}),
    gcseScienceQuestion("SCI-BIO1-06", "1SC0 Topic 3", "Two heterozygous parents have a child. What is the probability that the child inherits two recessive alleles?", {A:"0%",B:"25%",C:"50%",D:"75%"}, "B", "A cross of two heterozygous parents gives four equally likely allele combinations. One combination contains two recessive alleles, so the probability is 1/4 or 25%.", "BIO-GEN-02", {stem:"For two heterozygous parents, what is the probability of a dominant phenotype when the dominant allele is fully expressed?",options:{A:"25%",B:"50%",C:"75%",D:"100%"},correct:"C"}),
    gcseScienceQuestion("SCI-BIO1-07", "1SC0 Topic 4", "Why can a mutation sometimes produce a new characteristic?", {A:"It always improves survival",B:"It changes the DNA base sequence",C:"It removes every recessive allele",D:"It prevents all reproduction"}, "B", "A mutation changes the DNA base sequence. This may alter the protein made and therefore affect a characteristic, although many mutations have no observable effect.", "BIO-EVOL-01", {stem:"Which statement about mutations is most accurate?",options:{A:"All mutations are harmful",B:"Mutations only occur in gametes",C:"Mutations can create genetic variation",D:"Mutations are caused only by exercise"},correct:"C"}),
    gcseScienceQuestion("SCI-BIO1-08", "1SC0 Topic 4", "How does natural selection change the frequency of a useful allele in a population?", {A:"The allele is selected by the organism's needs",B:"Individuals with the allele leave more offspring",C:"The allele appears because the population tries",D:"Every individual gains the allele during life"}, "B", "Variation means some individuals are better adapted. They are more likely to survive and reproduce, so their alleles become more common over generations.", "BIO-EVOL-02", {stem:"What is a key condition for natural selection?",options:{A:"Inherited variation between individuals",B:"Identical offspring in every generation",C:"No competition for resources",D:"Traits acquired during exercise"},correct:"A"}),
    gcseScienceQuestion("SCI-BIO1-09", "1SC0 Topic 5", "Why are antibiotics ineffective against viruses?", {A:"Viruses have thicker cell walls",B:"Viruses are too large to enter",C:"Viruses lack the bacterial targets antibiotics act on",D:"Viruses can digest antibiotics"}, "C", "Antibiotics target bacterial structures or processes. Viruses reproduce inside host cells and do not have the same cellular targets.", "BIO-DISEASE-01", {stem:"What is one reason new antibiotic-resistant strains can spread quickly?",options:{A:"Resistance can be inherited by bacteria",B:"Antibiotics create useful organs",C:"All bacteria become viruses",D:"Resistance stops bacterial reproduction"},correct:"A"}),
    gcseScienceQuestion("SCI-BIO1-10", "1SC0 Topic 5", "What is the purpose of a control group in a drug trial?", {A:"To receive the largest dose",B:"To provide a comparison",C:"To guarantee a positive result",D:"To remove all variables"}, "B", "A control group provides a comparison with the treatment group. A placebo can help reduce the effects of expectation when appropriate.", "BIO-MED-01", {stem:"Why are double-blind trials useful?",options:{A:"They eliminate every risk",B:"They make a placebo active",C:"They reduce observer and participant bias",D:"They prevent data collection"},correct:"C"}),
    gcseScienceQuestion("SCI-BIO1-11", "1SC0 Topic 5", "What is vaccination intended to produce?", {A:"Memory cells that respond rapidly",B:"A permanent rise in body temperature",C:"More pathogenic microbes",D:"Immediate destruction of every pathogen"}, "A", "Vaccination exposes the immune system to harmless antigens. Memory cells can then trigger a faster, stronger response if the pathogen is encountered later.", "BIO-IMMUNE-01", {stem:"Why may a booster vaccination be needed?",options:{A:"To remove all white blood cells",B:"To strengthen or renew immune memory",C:"To make the pathogen reproduce",D:"To prevent antibody production"},correct:"B"}),
    gcseScienceQuestion("SCI-BIO1-12", "1SC0 Topic 5", "Why can monoclonal antibodies be useful in medicine?", {A:"They bind to one specific target",B:"They replace every enzyme",C:"They work only on healthy cells",D:"They increase all hormone levels"}, "A", "Monoclonal antibodies are identical antibodies made from a single clone of cells. Their specificity allows them to bind to a particular antigen or cell marker.", "BIO-MED-02", {stem:"What feature makes a monoclonal antibody specific?",options:{A:"It has no protein structure",B:"Its binding site fits a particular antigen",C:"It destroys every nearby cell",D:"It changes into a red blood cell"},correct:"B"})
  ]
};

BANKS["GCSE-SCI-CHEM-1"] = {
  label: "Chemistry 1 — Matter, Reactions, Metals & Equilibria",
  color: "#9a3412",
  questions: [
    gcseScienceQuestion("SCI-CHEM1-01", "1SC0 Topic 1", "What does the atomic number of an element show?", {A:"The number of neutrons",B:"The number of protons",C:"The total mass of the atom",D:"The number of shells"}, "B", "The atomic number equals the number of protons in the nucleus. In a neutral atom it also equals the number of electrons.", "CHEM-ATOM-01", {stem:"What is the mass number of an atom?",options:{A:"Protons plus neutrons",B:"Protons plus electrons",C:"Neutrons minus electrons",D:"Electrons in the outer shell"},correct:"A"}),
    gcseScienceQuestion("SCI-CHEM1-02", "1SC0 Topic 1", "Why do isotopes of an element have similar chemical properties?", {A:"They have the same number of protons",B:"They have identical masses",C:"They have no electrons",D:"They are all radioactive"}, "A", "Isotopes have the same electron arrangement because they have the same atomic number. Chemical reactions depend mainly on electrons.", "CHEM-ATOM-02", {stem:"How do isotopes of one element differ?",options:{A:"They have different proton numbers",B:"They have different neutron numbers",C:"They have different element symbols",D:"They have different chemical identities"},correct:"B"}),
    gcseScienceQuestion("SCI-CHEM1-03", "1SC0 Topic 2", "Which change is a physical change?", {A:"Burning methane",B:"Rusting iron",C:"Melting ice",D:"Reacting acid with metal"}, "C", "Melting changes the state of water but does not make a new substance. Chemical changes form new substances with different properties.", "CHEM-MATTER-01", {stem:"During boiling, what happens to the particles?",options:{A:"They become new atoms",B:"They gain spacing and move more freely",C:"They lose all energy",D:"They form a new compound"},correct:"B"}),
    gcseScienceQuestion("SCI-CHEM1-04", "1SC0 Topic 2", "Which method separates a soluble solid from a solution?", {A:"Filtration alone",B:"Evaporation or crystallisation",C:"Magnetic separation",D:"Decanting an insoluble solid"}, "B", "Evaporation removes solvent and crystallisation can obtain the dissolved solid. Filtration separates an insoluble solid from a liquid.", "CHEM-MIX-01", {stem:"Which technique separates different dyes in an ink sample?",options:{A:"Chromatography",B:"Titration",C:"Distillation only",D:"Precipitation"},correct:"A"}),
    gcseScienceQuestion("SCI-CHEM1-05", "1SC0 Topic 3", "What is the result when an acid reacts with a metal carbonate?", {A:"Salt, water and carbon dioxide",B:"Salt and hydrogen only",C:"Water and oxygen",D:"Metal and carbon"}, "A", "Acid plus metal carbonate produces a salt, water and carbon dioxide. The gas can be identified because it turns limewater cloudy.", "CHEM-REACTION-01", {stem:"What gas is usually formed when an acid reacts with a metal?",options:{A:"Oxygen",B:"Carbon dioxide",C:"Hydrogen",D:"Chlorine"},correct:"C"}),
    gcseScienceQuestion("SCI-CHEM1-06", "1SC0 Topic 3", "Why does a strong acid have a lower pH than a weak acid of the same concentration?", {A:"It contains more water",B:"It ionises more completely",C:"It has no hydrogen ions",D:"It is always more concentrated"}, "B", "A strong acid ionises almost completely in water, producing a higher concentration of hydrogen ions and therefore a lower pH.", "CHEM-ACID-01", {stem:"What does a pH decrease from 4 to 3 represent?",options:{A:"Ten times more hydrogen ions",B:"One tenth as many hydrogen ions",C:"No change in acidity",D:"A neutral solution"},correct:"A"}),
    gcseScienceQuestion("SCI-CHEM1-07", "1SC0 Topic 3", "What is the best way to prepare a pure, dry soluble salt from an acid and an insoluble base?", {A:"Add excess base, filter, then crystallise",B:"Use an indicator and boil to dryness",C:"Filter the acid before mixing",D:"Add water until no solid remains"}, "A", "Adding excess insoluble base ensures all acid reacts. The excess is filtered off, then the filtrate is concentrated and cooled to form crystals.", "CHEM-SALT-01", {stem:"Why is excess insoluble base removed by filtration?",options:{A:"It is a gas",B:"It did not dissolve or react further",C:"It neutralises the salt",D:"It makes the solution acidic"},correct:"B"}),
    gcseScienceQuestion("SCI-CHEM1-08", "1SC0 Topic 3", "In electrolysis of molten lead bromide, which particles carry charge through the liquid?", {A:"Electrons only",B:"Protons only",C:"Mobile ions",D:"Uncharged atoms"}, "C", "Molten ionic compounds contain mobile positive and negative ions. These ions move to opposite electrodes and carry charge through the electrolyte.", "CHEM-ELECTRO-01", {stem:"Which ion is discharged at the cathode during electrolysis?",options:{A:"A positive ion",B:"A negative ion",C:"A neutral molecule",D:"A proton from the wire"},correct:"A"}),
    gcseScienceQuestion("SCI-CHEM1-09", "1SC0 Topic 4", "Why can carbon be used to extract copper from copper oxide?", {A:"Carbon is more reactive than copper",B:"Copper is more reactive than carbon",C:"Carbon oxide is a metal",D:"Copper cannot form ions"}, "A", "Carbon is above copper in the reactivity series, so it can remove oxygen from copper oxide in a reduction reaction.", "CHEM-METALS-01", {stem:"What is the main raw material for extracting iron in a blast furnace?",options:{A:"Iron oxide ore",B:"Pure iron metal",C:"Copper carbonate",D:"Aluminium oxide only"},correct:"A"}),
    gcseScienceQuestion("SCI-CHEM1-10", "1SC0 Topic 4", "Why is electrolysis used to extract aluminium rather than carbon reduction?", {A:"Aluminium is less reactive than carbon",B:"Aluminium is more reactive than carbon",C:"Aluminium has no melting point",D:"Carbon cannot conduct electricity"}, "B", "Aluminium is more reactive than carbon, so its oxide is not reduced by carbon. Electrolysis is needed, although it uses considerable energy.", "CHEM-METALS-02", {stem:"What is one environmental cost of extracting aluminium by electrolysis?",options:{A:"High electricity demand",B:"No carbon dioxide is produced anywhere",C:"The ore becomes radioactive",D:"The metal cannot be recycled"},correct:"A"}),
    gcseScienceQuestion("SCI-CHEM1-11", "1SC0 Topic 4", "What happens to the position of equilibrium when more reactant is added?", {A:"It shifts to oppose the addition",B:"It always stops",C:"It shifts to make more products",D:"It removes the catalyst"}, "C", "Le Chatelier's principle predicts that equilibrium shifts in the direction that reduces the change. Adding a reactant favours the forward reaction.", "CHEM-EQ-01", {stem:"What does a catalyst do to a reversible reaction at equilibrium?",options:{A:"Changes the equilibrium yield",B:"Speeds both directions equally",C:"Removes one product",D:"Makes the reaction irreversible"},correct:"B"}),
    gcseScienceQuestion("SCI-CHEM1-12", "1SC0 Topic 4", "Why may industry use a compromise temperature for an exothermic equilibrium reaction?", {A:"High temperature gives faster rate but lower yield",B:"Low temperature gives no products",C:"Temperature has no effect",D:"High temperature always gives the highest yield"}, "A", "For an exothermic forward reaction, lower temperature favours products but slows the rate. Industry chooses a compromise between yield and production speed.", "CHEM-EQ-02", {stem:"What is the effect of increasing pressure on an equilibrium with fewer gas molecules on the product side?",options:{A:"It favours the side with fewer gas molecules",B:"It always favours reactants",C:"It has no possible effect",D:"It destroys the catalyst"},correct:"A"})
  ]
};

BANKS["GCSE-SCI-PHYS-1"] = {
  label: "Physics 1 — Motion, Energy, Waves, Light & Radioactivity",
  color: "#1d4ed8",
  questions: [
    gcseScienceQuestion("SCI-PHYS1-01", "1SC0 Topic 1", "A cyclist travels 150 m in 12 s. What is the average speed?", {A:"0.08 m/s",B:"12.5 m/s",C:"138 m/s",D:"1,800 m/s"}, "B", "Average speed = distance ÷ time = 150 ÷ 12 = 12.5 m/s. Always check that the units match the equation.", "PHYS-MOTION-01", {stem:"A car travels at 20 m/s for 15 s. What distance does it cover?",options:{A:"1.3 m",B:"35 m",C:"300 m",D:"750 m"},correct:"C"}),
    gcseScienceQuestion("SCI-PHYS1-02", "1SC0 Topic 1", "What is the difference between a scalar and a vector quantity?", {A:"A scalar has direction; a vector does not",B:"A vector has magnitude and direction",C:"Only vectors have units",D:"Scalars cannot be measured"}, "B", "A scalar has magnitude only, while a vector has both magnitude and direction. Speed is scalar; velocity is vector.", "PHYS-QUANT-01", {stem:"Which is a vector quantity?",options:{A:"Distance",B:"Speed",C:"Mass",D:"Velocity"},correct:"D"}),
    gcseScienceQuestion("SCI-PHYS1-03", "1SC0 Topic 2", "What does the gradient of a distance–time graph represent?", {A:"Acceleration",B:"Speed",C:"Force",D:"Energy"}, "B", "The gradient is change in distance divided by change in time, which is speed. A steeper line represents a greater speed.", "PHYS-GRAPH-01", {stem:"What does a horizontal section on a distance–time graph show?",options:{A:"The object is stationary",B:"The object is accelerating",C:"The object has zero mass",D:"The object is moving fastest"},correct:"A"}),
    gcseScienceQuestion("SCI-PHYS1-04", "1SC0 Topic 2", "A resultant force acts on an object. What must happen?", {A:"Its mass changes",B:"It accelerates",C:"It becomes stationary",D:"Its temperature falls"}, "B", "A non-zero resultant force causes acceleration. The acceleration may be a change in speed, direction or both.", "PHYS-FORCE-01", {stem:"What is the resultant force when an object moves at constant velocity?",options:{A:"Zero",B:"Equal to its weight",C:"Greater than its mass",D:"Always forwards"},correct:"A"}),
    gcseScienceQuestion("SCI-PHYS1-05", "1SC0 Topic 2", "Which equation links force, mass and acceleration?", {A:"F = m ÷ a",B:"F = m × a",C:"F = a ÷ m",D:"F = m + a"}, "B", "Newton's second law is F = m × a. The force is measured in newtons when mass is in kilograms and acceleration in m/s².", "PHYS-FORCE-02", {stem:"A 4 kg trolley accelerates at 3 m/s². What is the resultant force?",options:{A:"0.75 N",B:"1.3 N",C:"7 N",D:"12 N"},correct:"D"}),
    gcseScienceQuestion("SCI-PHYS1-06", "1SC0 Topic 3", "Which statement describes conservation of energy?", {A:"Energy is destroyed by friction",B:"Energy is created in batteries",C:"Energy is transferred, not created or destroyed",D:"Only useful energy is conserved"}, "C", "The total energy of a closed system remains constant. Transfers may spread energy to the surroundings, often by heating.", "PHYS-ENERGY-01", {stem:"What happens to energy dissipated by friction?",options:{A:"It disappears",B:"It is transferred to the thermal store",C:"It becomes mass",D:"It stops existing in a closed system"},correct:"B"}),
    gcseScienceQuestion("SCI-PHYS1-07", "1SC0 Topic 3", "A 2 kg object is lifted 5 m. Using g = 10 N/kg, what is its gravitational potential energy increase?", {A:"4 J",B:"10 J",C:"25 J",D:"100 J"}, "D", "Gravitational potential energy change = mass × gravitational field strength × height = 2 × 10 × 5 = 100 J.", "PHYS-ENERGY-02", {stem:"Which change increases the gravitational potential energy gained when lifting an object?",options:{A:"A smaller height",B:"A smaller mass",C:"A greater height",D:"A lower gravitational field strength"},correct:"C"}),
    gcseScienceQuestion("SCI-PHYS1-08", "1SC0 Topic 4", "Which feature is common to all transverse waves?", {A:"Oscillations are parallel to travel",B:"Oscillations are perpendicular to travel",C:"They require a vacuum",D:"They cannot be reflected"}, "B", "In a transverse wave, the vibrations are at right angles to the direction of energy transfer. Light and water waves are examples.", "PHYS-WAVES-01", {stem:"What is the frequency of a wave with a period of 0.25 s?",options:{A:"0.25 Hz",B:"2 Hz",C:"4 Hz",D:"25 Hz"},correct:"C"}),
    gcseScienceQuestion("SCI-PHYS1-09", "1SC0 Topic 4", "What happens when a wave is refracted as it enters a different medium?", {A:"Its speed and direction may change",B:"Its energy is always destroyed",C:"Its frequency must become zero",D:"It becomes radioactive"}, "A", "Refraction occurs because wave speed changes at a boundary. This can change direction; frequency remains set by the source.", "PHYS-WAVES-02", {stem:"What is the amplitude of a wave most closely related to?",options:{A:"The energy transferred",B:"The wave's frequency only",C:"The time period only",D:"The number of particles"},correct:"A"}),
    gcseScienceQuestion("SCI-PHYS1-10", "1SC0 Topic 5", "Which type of electromagnetic radiation has the shortest wavelength?", {A:"Radio waves",B:"Infrared",C:"Ultraviolet",D:"Gamma rays"}, "D", "Gamma rays have the shortest wavelength and highest frequency in the electromagnetic spectrum. They also carry the most energy per photon.", "PHYS-EM-01", {stem:"Which electromagnetic radiation is used in thermal imaging?",options:{A:"Infrared",B:"Gamma rays",C:"Ultraviolet",D:"Radio waves"},correct:"A"}),
    gcseScienceQuestion("SCI-PHYS1-11", "1SC0 Topic 5", "Why does a converging lens bring parallel rays to a focus?", {A:"It absorbs all light",B:"It refracts rays toward a focal point",C:"It reflects rays backwards",D:"It converts light to sound"}, "B", "A converging lens refracts rays so that parallel rays meet at the principal focus. The focal length is the distance from the lens to that point.", "PHYS-LIGHT-01", {stem:"What type of image can a converging lens form when an object is beyond 2F?",options:{A:"Real, inverted and smaller",B:"Virtual, upright and larger",C:"Real, upright and larger",D:"No image"},correct:"A"}),
    gcseScienceQuestion("SCI-PHYS1-12", "1SC0 Topic 6", "What does the half-life of a radioactive isotope describe?", {A:"The time for all nuclei to decay",B:"The time for half the unstable nuclei to decay",C:"The age of the sample",D:"The time for radiation to stop"}, "B", "Half-life is the time taken for the number of undecayed nuclei, or the activity, to halve. Decay is random for individual nuclei.", "PHYS-RAD-01", {stem:"Which radiation is the most ionising?",options:{A:"Alpha",B:"Beta",C:"Gamma",D:"Visible light"},correct:"A"})
  ]
};

SUBJECTS["gcse-science"] = {
  label: "GCSE Combined Science",
  sub: "Pearson Edexcel 1SC0 — Papers 1–3",
  color: "#166534",
  banks: ["GCSE-SCI-BIO-1", "GCSE-SCI-CHEM-1", "GCSE-SCI-PHYS-1"]
};

const moveGcseScienceAnswer = (question, target, reforge = false) => {
  const item = reforge ? question.reforge : question;
  if (item.correct !== target) [item.options[item.correct], item.options[target]] = [item.options[target], item.options[item.correct]];
  item.correct = target;
};
const gcseScienceAnswerPlans = {
  "GCSE-SCI-BIO-1": ["ABCDABCDABCD", "CDABCDABCDAB"],
  "GCSE-SCI-CHEM-1": ["BCDABCDABCDA", "DABCDABCDABC"],
  "GCSE-SCI-PHYS-1": ["CDABCDABCDAB", "ABCDABCDABCD"]
};
for (const [bankId, [basePlan, reforgePlan]] of Object.entries(gcseScienceAnswerPlans)) {
  BANKS[bankId].questions.forEach((question, index) => {
    moveGcseScienceAnswer(question, basePlan[index % basePlan.length]);
    moveGcseScienceAnswer(question, reforgePlan[index % reforgePlan.length], true);
  });
}
// Keep options comparable in length after answer-position balancing. The
// scaffold carries the full explanation, so the selected option can stay
// concise and should not reveal itself by being a mini-mark-scheme.
const gcseScienceConciseAnswers = {
  "SCI-BIO1-01:base":"A cell membrane", "SCI-BIO1-01:reforge":"Cell membrane",
  "SCI-BIO1-02:reforge":"0.2 mm", "SCI-BIO1-03:reforge":"Mitochondrion",
  "SCI-BIO1-04:base":"Growth and tissue repair", "SCI-BIO1-05:reforge":"Phenotype",
  "SCI-BIO1-07:reforge":"Genetic variation", "SCI-BIO1-08:base":"More offspring from carriers",
  "SCI-BIO1-09:base":"No bacterial drug target", "SCI-BIO1-10:reforge":"Less trial bias",
  "SCI-BIO1-11:reforge":"Renew immune memory", "SCI-BIO1-12:reforge":"Specific antigen binding",
  "SCI-CHEM1-02:base":"Different neutron numbers", "SCI-CHEM1-03:reforge":"Particles spread apart",
  "SCI-CHEM1-04:base":"Chromatography", "SCI-CHEM1-05:base":"Hydrogen",
  "SCI-CHEM1-07:base":"Unreacted solid", "SCI-CHEM1-07:reforge":"It did not dissolve",
  "SCI-CHEM1-12:base":"Faster rate, lower yield", "SCI-CHEM1-12:reforge":"Fewer gas molecules",
  "SCI-PHYS1-06:base":"Thermal store", "SCI-PHYS1-06:reforge":"Thermal energy",
  "SCI-PHYS1-07:base":"Greater height", "SCI-PHYS1-08:base":"Perpendicular vibrations",
  "SCI-PHYS1-09:base":"Speed and direction may change", "SCI-PHYS1-11:base":"Real, inverted, smaller",
  "SCI-PHYS1-12:base":"Half the nuclei decay"
};
for (const bankId of SUBJECTS["gcse-science"].banks) {
  for (const question of BANKS[bankId].questions) {
    for (const [mode, item] of [["base", question], ["reforge", question.reforge]]) {
      const concise = gcseScienceConciseAnswers[`${question.id}:${mode}`];
      if (concise) item.options[item.correct] = concise;
    }
  }
}

