BANKS["GCSE-SCI-BIO-2"] = {
  label: "Biology 2 — Plants, Coordination, Transport & Ecosystems",
  color: "#15803d",
  questions: [
    gcseScienceQuestion("SCI-BIO2-01", "1SC0 Topic 1", "What is the main role of chlorophyll in photosynthesis?", {A:"Absorbing light energy",B:"Releasing carbon dioxide",C:"Breaking down glucose",D:"Transporting water"}, "A", "Chlorophyll absorbs light energy, which is used to drive the reactions that make glucose from carbon dioxide and water.", "BIO-PLANT-01", {stem:"Which gas is taken in by a leaf for photosynthesis?",options:{A:"Oxygen",B:"Carbon dioxide",C:"Nitrogen",D:"Hydrogen"},correct:"B"}),
    gcseScienceQuestion("SCI-BIO2-02", "1SC0 Topic 6", "Why are root hair cells effective at absorbing water and mineral ions?", {A:"They have a large surface area",B:"They contain no cytoplasm",C:"They are covered by wax",D:"They have no cell membrane"}, "A", "Root hair cells have a long extension that provides a large surface area. Their membranes and transport proteins help absorb water and mineral ions from the soil.", "BIO-PLANT-02", {stem:"How does water enter a root hair cell?",options:{A:"By active transport only",B:"By osmosis",C:"By digestion",D:"By transpiration from the root"},correct:"B"}),
    gcseScienceQuestion("SCI-BIO2-03", "1SC0 Topic 6", "What is the function of xylem tissue?", {A:"Transporting water and mineral ions",B:"Transporting sugars from leaves",C:"Making pollen grains",D:"Controlling stomata only"}, "A", "Xylem vessels carry water and mineral ions from roots towards the leaves. They are strengthened with lignin and form continuous tubes.", "BIO-TRANSPORT-01", {stem:"Which tissue transports sucrose around a plant?",options:{A:"Xylem",B:"Phloem",C:"Epidermis",D:"Meristem"},correct:"B"}),
    gcseScienceQuestion("SCI-BIO2-04", "1SC0 Topic 6", "Why does transpiration usually increase when temperature rises?", {A:"Water molecules gain kinetic energy",B:"The leaf makes less glucose",C:"Stomata always close",D:"Roots stop absorbing ions"}, "A", "Higher temperature increases evaporation from mesophyll cells and diffusion of water vapour through stomata, increasing the transpiration rate if other factors are constant.", "BIO-TRANS-02", {stem:"What is the effect of strong wind on transpiration?",options:{A:"It removes humid air near the leaf",B:"It stops evaporation completely",C:"It reduces the diffusion gradient",D:"It closes every stomata"},correct:"A"}),
    gcseScienceQuestion("SCI-BIO2-05", "1SC0 Topic 7", "Which part of the nervous system carries impulses from receptors to the central nervous system?", {A:"Motor neurone",B:"Relay neurone",C:"Sensory neurone",D:"Effector"}, "C", "Sensory neurones carry impulses from receptors towards the central nervous system. Motor neurones carry impulses to effectors.", "BIO-NERVE-01", {stem:"What is the role of a synapse?",options:{A:"It connects bones",B:"It transfers a signal between neurones",C:"It pumps blood",D:"It produces antibodies"},correct:"B"}),
    gcseScienceQuestion("SCI-BIO2-06", "1SC0 Topic 7", "What is a reflex action?", {A:"A slow conscious decision",B:"A rapid automatic response",C:"A response that needs no receptor",D:"A learned movement only"}, "B", "Reflexes are rapid and automatic. They protect the body and are coordinated through a reflex arc, often without conscious involvement first.", "BIO-REFLEX-01", {stem:"Why are reflex actions useful?",options:{A:"They delay responses",B:"They reduce the chance of injury",C:"They require detailed thought",D:"They prevent all movement"},correct:"B"}),
    gcseScienceQuestion("SCI-BIO2-07", "1SC0 Topic 7", "How does insulin help regulate blood glucose concentration?", {A:"It increases uptake and storage of glucose",B:"It converts glycogen into glucose",C:"It prevents cells using glucose",D:"It raises blood glucose directly"}, "A", "When blood glucose rises, insulin causes cells to take up more glucose and promotes conversion of glucose to glycogen in the liver and muscles.", "BIO-HOMEOSTASIS-01", {stem:"What happens when blood glucose becomes too low?",options:{A:"Glucagon promotes glucose release",B:"Insulin always increases",C:"The pancreas stops working",D:"Glycogen becomes more stored"},correct:"A"}),
    gcseScienceQuestion("SCI-BIO2-08", "1SC0 Topic 8", "Why do mammals need a double circulatory system?", {A:"It keeps blood at suitable pressure",B:"It prevents oxygen entering blood",C:"It removes the need for a heart",D:"It sends all blood to the lungs twice"}, "A", "The right side pumps blood to the lungs at lower pressure, while the left side pumps oxygenated blood to the body at higher pressure. This supports efficient delivery.", "BIO-CIRC-01", {stem:"Which chamber pumps oxygenated blood to the body?",options:{A:"Right atrium",B:"Right ventricle",C:"Left atrium",D:"Left ventricle"},correct:"D"}),
    gcseScienceQuestion("SCI-BIO2-09", "1SC0 Topic 8", "How are alveoli adapted for gas exchange?", {A:"They have a thin wall and large surface area",B:"They have thick dry walls",C:"They contain cartilage rings",D:"They prevent diffusion"}, "A", "Many alveoli provide a large surface area. Their walls are one cell thick and have a good blood supply, maintaining steep concentration gradients.", "BIO-GAS-01", {stem:"What process moves oxygen from alveoli into the blood?",options:{A:"Active transport",B:"Diffusion",C:"Osmosis",D:"Filtration"},correct:"B"}),
    gcseScienceQuestion("SCI-BIO2-10", "1SC0 Topic 9", "Why is energy transferred between trophic levels inefficient?", {A:"Some material is not eaten or digested",B:"Producers absorb all energy",C:"Consumers never respire",D:"Energy is created by decomposers"}, "A", "Energy is lost through uneaten material, waste, movement and heat released by respiration. Only a fraction becomes biomass available to the next level.", "BIO-ECOSYSTEM-01", {stem:"What is the original energy source for most food chains?",options:{A:"Mineral ions",B:"Light from the Sun",C:"Decomposer heat",D:"Nitrate fertiliser"},correct:"B"}),
    gcseScienceQuestion("SCI-BIO2-11", "1SC0 Topic 9", "What is the role of decomposers in the carbon cycle?", {A:"They release carbon dioxide during respiration",B:"They remove all carbon from soil",C:"They make fossil fuels instantly",D:"They stop decay"}, "A", "Decomposers break down dead material and waste. Their respiration returns carbon dioxide to the atmosphere while nutrients are recycled into soil.", "BIO-CYCLE-01", {stem:"Which process removes carbon dioxide from the atmosphere?",options:{A:"Combustion",B:"Respiration",C:"Photosynthesis",D:"Decay"},correct:"C"}),
    gcseScienceQuestion("SCI-BIO2-12", "1SC0 Topic 9", "Why can fertiliser runoff cause fish deaths in a lake?", {A:"It can cause algal growth and oxygen depletion",B:"It removes all minerals from water",C:"It stops bacteria decomposing",D:"It makes every fish produce more oxygen"}, "A", "Nitrates can cause algal blooms. When algae die, decomposers respire while breaking them down, reducing dissolved oxygen and causing fish to suffocate.", "BIO-HUMAN-01", {stem:"What is eutrophication?",options:{A:"Nutrient enrichment causing oxygen loss",B:"The natural formation of a new species",C:"A decrease in all plant growth",D:"The removal of carbon from air"},correct:"A"})
  ]
};

BANKS["GCSE-SCI-CHEM-2"] = {
  label: "Chemistry 2 — Groups, Rates, Energy, Fuels & Earth Science",
  color: "#c2410c",
  questions: [
    gcseScienceQuestion("SCI-CHEM2-01", "1SC0 Topic 1", "Why do elements in the same group have similar chemical properties?", {A:"They have the same number of outer-shell electrons",B:"They have the same mass number",C:"They are all gases",D:"They have identical nuclei"}, "A", "Elements in a group have the same number of electrons in their outer shell. This gives them similar patterns of chemical reactivity.", "CHEM-GROUP-01", {stem:"What happens to reactivity down Group 1?",options:{A:"It generally increases",B:"It always becomes zero",C:"It generally decreases",D:"It stays identical"},correct:"A"}),
    gcseScienceQuestion("SCI-CHEM2-02", "1SC0 Topic 6", "What observation is expected when chlorine water is added to potassium bromide solution?", {A:"The solution becomes orange-brown",B:"A blue precipitate forms",C:"The solution becomes colourless",D:"Hydrogen is released"}, "A", "Chlorine is more reactive than bromine and displaces bromine from bromide ions. The dissolved bromine gives an orange-brown colour.", "CHEM-HALOGEN-01", {stem:"Why can chlorine displace bromide ions?",options:{A:"Chlorine is the more reactive halogen",B:"Bromine has no electrons",C:"Chlorine is a metal",D:"Bromide ions are positive"},correct:"A"}),
    gcseScienceQuestion("SCI-CHEM2-03", "1SC0 Topic 6", "What is a characteristic of the noble gases?", {A:"They have full outer electron shells",B:"They react violently with water",C:"They form acidic metals",D:"They have one outer electron"}, "A", "Noble gases have stable electron arrangements, so they are very unreactive under ordinary conditions.", "CHEM-NOBLE-01", {stem:"Why is helium used in some balloons?",options:{A:"It is less dense than air and unreactive",B:"It burns more safely than oxygen",C:"It reacts with rubber",D:"It is denser than water"},correct:"A"}),
    gcseScienceQuestion("SCI-CHEM2-04", "1SC0 Topic 7", "Which change usually increases the rate of a reaction between two solids?", {A:"Using smaller pieces",B:"Lowering temperature",C:"Reducing surface area",D:"Removing collisions"}, "A", "Smaller pieces provide a larger surface area, so particles can collide more frequently. The effect is strongest when other variables are controlled.", "CHEM-RATE-01", {stem:"Why does a higher temperature usually increase reaction rate?",options:{A:"Particles collide less often",B:"More particles exceed activation energy",C:"The products disappear",D:"The reactants become heavier"},correct:"B"}),
    gcseScienceQuestion("SCI-CHEM2-05", "1SC0 Topic 7", "What does a catalyst do in a chemical reaction?", {A:"Provides an alternative lower-energy pathway",B:"Changes the products permanently",C:"Raises the activation energy",D:"Is used up as a reactant"}, "A", "A catalyst lowers the activation energy by providing another pathway. It is not used up and does not change the equilibrium position.", "CHEM-RATE-02", {stem:"How can a reaction rate be measured from a graph?",options:{A:"By finding the initial gradient",B:"By reading the final colour only",C:"By counting atoms in the beaker",D:"By multiplying time by temperature"},correct:"A"}),
    gcseScienceQuestion("SCI-CHEM2-06", "1SC0 Topic 7", "What is an exothermic reaction?", {A:"It transfers energy to the surroundings",B:"It always needs a flame",C:"It absorbs heat from the surroundings",D:"It has no energy change"}, "A", "In an exothermic reaction, the products have less chemical energy than the reactants and energy is transferred to the surroundings, often warming them.", "CHEM-ENERGY-01", {stem:"What happens to the temperature of the surroundings in an exothermic reaction?",options:{A:"It usually rises",B:"It always falls",C:"It becomes absolute zero",D:"It cannot be measured"},correct:"A"}),
    gcseScienceQuestion("SCI-CHEM2-07", "1SC0 Topic 7", "A reaction transfers 600 J in 20 s. What is its power?", {A:"30 W",B:"300 W",C:"580 W",D:"12,000 W"}, "A", "Power = energy transferred ÷ time = 600 ÷ 20 = 30 W.", "CHEM-ENERGY-02", {stem:"What is the energy change when bonds form?",options:{A:"Energy is released",B:"Energy is never involved",C:"All energy is destroyed",D:"Only light is created"},correct:"A"}),
    gcseScienceQuestion("SCI-CHEM2-08", "1SC0 Topic 8", "Why is crude oil separated by fractional distillation?", {A:"Its hydrocarbons have different boiling points",B:"All fractions have the same formula",C:"It creates new elements",D:"It removes every impurity by filtration"}, "A", "Fractional distillation separates hydrocarbons because their molecules have different boiling points. The fractions have different properties and uses.", "CHEM-FUEL-01", {stem:"What is a hydrocarbon?",options:{A:"A compound of carbon and hydrogen",B:"A mixture of metals",C:"A carbon-free salt",D:"An oxygen isotope"},correct:"A"}),
    gcseScienceQuestion("SCI-CHEM2-09", "1SC0 Topic 8", "Why is cracking useful in the petrochemical industry?", {A:"It makes shorter-chain alkenes and alkanes",B:"It turns all fuels into metals",C:"It removes carbon dioxide from air",D:"It produces only water"}, "A", "Cracking breaks long-chain hydrocarbons into shorter, more useful molecules. It can produce alkenes for polymers as well as smaller alkanes for fuels.", "CHEM-FUEL-02", {stem:"What test identifies an alkene?",options:{A:"Bromine water becomes colourless",B:"Limewater turns cloudy",C:"A glowing splint relights",D:"Universal indicator becomes purple"},correct:"A"}),
    gcseScienceQuestion("SCI-CHEM2-10", "1SC0 Topic 8", "What is one environmental concern linked to burning fossil fuels?", {A:"Carbon dioxide can contribute to climate change",B:"They produce no gases",C:"They remove oxygen permanently",D:"They stop all acid rain"}, "A", "Combustion of fossil fuels releases carbon dioxide. Increased atmospheric carbon dioxide strengthens the greenhouse effect and can contribute to climate change.", "CHEM-EARTH-01", {stem:"Which pollutant can cause acid rain?",options:{A:"Sulfur dioxide",B:"Helium",C:"Nitrogen gas",D:"Water vapour"},correct:"A"}),
    gcseScienceQuestion("SCI-CHEM2-11", "1SC0 Topic 8", "Why is potable water not necessarily pure water?", {A:"It is safe to drink but may contain dissolved substances",B:"It contains no water molecules",C:"It is always distilled",D:"It must contain pathogens"}, "A", "Potable water is treated to be safe to drink, but it can still contain dissolved minerals. Pure water contains only water molecules.", "CHEM-WATER-01", {stem:"Which process can make water potable from a fresh water source?",options:{A:"Filtration and sterilisation",B:"Adding more pathogens",C:"Burning the water",D:"Removing every dissolved gas"},correct:"A"}),
    gcseScienceQuestion("SCI-CHEM2-12", "1SC0 Topic 8", "Why is recycling metals often more sustainable than extracting new ores?", {A:"It usually uses less energy and reduces mining",B:"It creates unlimited raw materials",C:"It prevents every emission",D:"It makes metals non-conductive"}, "A", "Recycling can reduce energy use, mining damage and waste. Its environmental benefit depends on collection, sorting and the energy source used.", "CHEM-RESOURCES-01", {stem:"What is one reason aluminium recycling saves energy?",options:{A:"Remelting uses less energy than electrolysis",B:"Aluminium cannot be melted",C:"Ore extraction needs no electricity",D:"Recycling removes all transport"},correct:"A"})
  ]
};

BANKS["GCSE-SCI-PHYS-2"] = {
  label: "Physics 2 — Electricity, Magnetism, Particles & Forces in Matter",
  color: "#2563eb",
  questions: [
    gcseScienceQuestion("SCI-PHYS2-01", "1SC0 Topic 1", "What is the unit of potential difference?", {A:"Ampere",B:"Volt",C:"Ohm",D:"Watt"}, "B", "Potential difference is measured in volts (V). It is the energy transferred per unit charge between two points.", "PHYS-ELEC-01", {stem:"What is the unit of current?",options:{A:"Ampere",B:"Volt",C:"Joule",D:"Ohm"},correct:"A"}),
    gcseScienceQuestion("SCI-PHYS2-02", "1SC0 Topic 10", "A current of 3 A flows through a 4 Ω resistor. What is the potential difference?", {A:"0.75 V",B:"1.33 V",C:"7 V",D:"12 V"}, "D", "Using V = I × R, the potential difference is 3 × 4 = 12 V.", "PHYS-ELEC-02", {stem:"A 12 V supply drives 3 A through a component. What is its resistance?",options:{A:"0.25 Ω",B:"4 Ω",C:"9 Ω",D:"36 Ω"},correct:"B"}),
    gcseScienceQuestion("SCI-PHYS2-03", "1SC0 Topic 10", "Why are components connected in parallel in a domestic circuit?", {A:"Each branch receives the supply potential difference",B:"One component controls every branch",C:"The circuit has no current",D:"The cables cannot carry charge"}, "A", "In parallel, each branch is connected across the supply. Appliances can operate independently and one branch failing need not break the others.", "PHYS-CIRCUIT-01", {stem:"What happens if one appliance in a parallel circuit is switched off?",options:{A:"All other branches must stop",B:"The other branches can continue",C:"The supply voltage becomes zero",D:"Current flows backwards"},correct:"B"}),
    gcseScienceQuestion("SCI-PHYS2-04", "1SC0 Topic 10", "What is the purpose of a fuse in a plug?", {A:"It melts if current becomes too large",B:"It increases the supply voltage",C:"It stores charge indefinitely",D:"It makes the appliance more efficient"}, "A", "A fuse contains a wire that melts when excessive current causes heating. This breaks the circuit and helps prevent damage or fire.", "PHYS-SAFETY-01", {stem:"Why is the earth wire important in a metal-cased appliance?",options:{A:"It provides a low-resistance path for fault current",B:"It supplies extra power during normal use",C:"It stops all current in the live wire",D:"It stores the appliance's energy"},correct:"A"}),
    gcseScienceQuestion("SCI-PHYS2-05", "1SC0 Topic 8", "What does it mean when a force does work on an object?", {A:"Energy is transferred by the force",B:"The object must stop",C:"The force becomes mass",D:"No displacement is possible"}, "A", "Work done is the energy transferred when a force causes movement in its direction. W = F × d for a constant force along the displacement.", "PHYS-WORK-01", {stem:"A 20 N force moves an object 3 m in its direction. How much work is done?",options:{A:"6.7 J",B:"23 J",C:"60 J",D:"600 J"},correct:"C"}),
    gcseScienceQuestion("SCI-PHYS2-06", "1SC0 Topic 9", "What happens to the extension of a spring when the force increases within its limit of proportionality?", {A:"It increases in proportion to the force",B:"It becomes zero",C:"It decreases automatically",D:"It becomes independent of force"}, "A", "Within the limit of proportionality, extension is directly proportional to force. Beyond the elastic limit, the spring may not return to its original length.", "PHYS-SPRINGS-01", {stem:"What is elastic deformation?",options:{A:"A material returns to its original shape",B:"A material always breaks",C:"A material gains mass",D:"A force disappears"},correct:"A"}),
    gcseScienceQuestion("SCI-PHYS2-07", "1SC0 Topic 12", "What is the motor effect?", {A:"A current-carrying conductor experiences a force in a magnetic field",B:"A magnet loses all field",C:"A wire becomes radioactive",D:"A current stops in a field"}, "A", "The motor effect occurs when a current-carrying conductor is placed in a magnetic field. The force direction depends on the field and current directions.", "PHYS-MAG-01", {stem:"How can the force on a current-carrying wire be increased?",options:{A:"Increase current or magnetic field strength",B:"Remove the magnetic field",C:"Reduce the wire length to zero",D:"Stop the current"},correct:"A"}),
    gcseScienceQuestion("SCI-PHYS2-08", "1SC0 Topic 13", "What is electromagnetic induction?", {A:"A potential difference produced by changing magnetic flux",B:"A current created by heating a resistor",C:"A magnet made from plastic",D:"A charge stored in an insulator"}, "A", "Moving a magnet relative to a coil changes the magnetic flux and induces a potential difference. A current flows if the circuit is complete.", "PHYS-INDUCTION-01", {stem:"How can the induced potential difference be increased?",options:{A:"Move the magnet faster",B:"Hold the magnet still",C:"Use fewer coil turns only",D:"Remove the magnetic field"},correct:"A"}),
    gcseScienceQuestion("SCI-PHYS2-09", "1SC0 Topic 14", "Why does gas pressure increase when a sealed gas is heated?", {A:"Particles collide with the walls more often and harder",B:"Particles stop moving",C:"The gas loses all mass",D:"The container becomes empty"}, "A", "Heating increases the particles' average kinetic energy. They collide with the walls more frequently and with greater force, increasing pressure at constant volume.", "PHYS-PARTICLE-01", {stem:"What is absolute zero?",options:{A:"The lowest possible temperature",B:"The hottest gas temperature",C:"The pressure of a vacuum",D:"The melting point of iron"},correct:"A"}),
    gcseScienceQuestion("SCI-PHYS2-10", "1SC0 Topic 14", "What is density?", {A:"Mass divided by volume",B:"Volume divided by mass",C:"Mass multiplied by force",D:"Weight divided by time"}, "A", "Density is ρ = m ÷ V. A dense material has a large mass for its volume compared with a less dense material.", "PHYS-DENSITY-01", {stem:"A block has mass 600 g and volume 200 cm³. What is its density?",options:{A:"0.33 g/cm³",B:"3 g/cm³",C:"400 g/cm³",D:"120,000 g/cm³"},correct:"B"}),
    gcseScienceQuestion("SCI-PHYS2-11", "1SC0 Topic 15", "Why does an object float when placed in a liquid?", {A:"Upthrust balances or exceeds its weight",B:"Its mass becomes zero",C:"Gravity stops acting",D:"The liquid has no particles"}, "A", "An object floats when the upthrust from the displaced liquid balances its weight. If upthrust is initially greater, the object rises until equilibrium.", "PHYS-FLOAT-01", {stem:"What affects the upthrust on a submerged object?",options:{A:"The volume of fluid displaced",B:"The object's colour",C:"The sound it makes",D:"The number of electrons only"},correct:"A"}),
    gcseScienceQuestion("SCI-PHYS2-12", "1SC0 Topic 15", "What is the relationship between pressure, force and area?", {A:"Pressure = force ÷ area",B:"Pressure = force × area",C:"Pressure = area ÷ force",D:"Pressure = force + area"}, "A", "Pressure is force divided by the area over which it acts. The same force produces greater pressure when applied over a smaller area.", "PHYS-PRESSURE-01", {stem:"Why does a sharp knife cut more easily than a blunt one?",options:{A:"The sharp edge applies force over a smaller area",B:"The sharp edge removes gravity",C:"The blunt edge has no mass",D:"The sharp edge stops friction"},correct:"A"})
  ]
};

SUBJECTS["gcse-science"].banks.push("GCSE-SCI-BIO-2", "GCSE-SCI-CHEM-2", "GCSE-SCI-PHYS-2");
SUBJECTS["gcse-science"].sub = "Pearson Edexcel 1SC0 — Papers 1–6";

