for (const bankId of ["GCSE-SCI-BIO-2", "GCSE-SCI-CHEM-2", "GCSE-SCI-PHYS-2"]) {
  for (const question of BANKS[bankId].questions.slice(-12)) {
    for (const [mode, item] of [["base", question], ["reforge", question.reforge]]) {
      const concise = gcseSciencePaper46ConciseAnswers[`${question.id}:${mode}`];
      if (concise) item.options[item.correct] = concise;
    }
  }
}

// Fix an ungradeable Reforge item: B must differ from the correct 0.2 mm.
const gcseScienceBio1Microscope = BANKS["GCSE-SCI-BIO-1"].questions.find(question => question.id === "SCI-BIO1-02");
if (gcseScienceBio1Microscope) gcseScienceBio1Microscope.reforge.options.B = "0.02 mm";

// Replace the six duplicated GCSE Economics stems with distinct specification coverage.
const replaceGcseEconomicsQuestion = (bankId, id, replacement) => {
  const index = BANKS[bankId].questions.findIndex(question => question.id === id);
  if (index !== -1) BANKS[bankId].questions[index] = replacement;
};
replaceGcseEconomicsQuestion("GCSE-ECON-P1-PROD", "GCSE-P1-PRD-12", {id:"GCSE-P1-PRD-12",spec:"GCSE-ECON-P1-PROD",stem:"How can technical economies of scale lower a firm's average cost?",options:{A:"Specialist machinery can spread fixed costs over more output",B:"The firm stops using capital",C:"Every worker performs every task",D:"The firm buys inputs at a higher price"},correct:"A",tag:"MC-GCSE-P1-PRD-12",scaffold:"Technical economies can arise when large firms use specialised machinery efficiently. The fixed cost of that equipment is spread across a larger output, reducing average cost if utilisation is high.",reforge:{stem:"Which is an example of a managerial economy of scale?",options:{A:"A large firm employs specialist managers",B:"A firm ends up paying much more for each and every input it buys",C:"A firm loses all coordination between its separate departments",D:"A small shop buys one product"},correct:"A"}});
replaceGcseEconomicsQuestion("GCSE-ECON-P1-MONEY", "GCSE-P1-MNY-11", {id:"GCSE-P1-MNY-11",spec:"GCSE-ECON-P1-MONEY",stem:"Why might a lender check a borrower's credit history?",options:{A:"To assess the risk of non-repayment",B:"To guarantee no interest is charged",C:"To remove the need for collateral",D:"To make saving impossible"},correct:"A",tag:"MC-GCSE-P1-MNY-11",scaffold:"A credit history gives information about past repayments and helps a lender judge default risk. A riskier borrower may face a higher interest rate or be refused credit.",reforge:{stem:"What may happen if a borrower misses loan repayments?",options:{A:"Their future access to credit may become harder",B:"The loan automatically becomes entirely free of any further charge",C:"The lender's risk disappears",D:"Their income is guaranteed to rise enough to cover the shortfall"},correct:"A"}});
replaceGcseEconomicsQuestion("GCSE-ECON-P1-MONEY", "GCSE-P1-MNY-13", {id:"GCSE-P1-MNY-13",spec:"GCSE-ECON-P1-MONEY",stem:"What is an insurance premium?",options:{A:"The payment made for insurance cover",B:"The value of every claim paid",C:"A tax on all saving",D:"The loss that cannot be covered"},correct:"A",tag:"MC-GCSE-P1-MNY-13",scaffold:"A premium is the amount paid by a policyholder for insurance cover, usually at regular intervals or when the policy begins. The insurer then assesses valid claims against the policy terms.",reforge:{stem:"What is an insurance excess?",options:{A:"The amount the policyholder pays towards a claim",B:"The insurer's total annual profit across all of its policies",C:"A guaranteed payout made for every single event that is claimed for",D:"A bank's lending rate"},correct:"A"}});
replaceGcseEconomicsQuestion("GCSE-ECON-P2-NATIONAL", "GCSE-P2-NAT-11", {id:"GCSE-P2-NAT-11",spec:"GCSE-ECON-P2-NATIONAL",stem:"How might an ageing population affect the tax base?",options:{A:"A smaller share of working-age people may pay income tax",B:"Every person's tax payment must rise",C:"The labour force automatically doubles",D:"Pension spending disappears"},correct:"A",tag:"MC-GCSE-P2-NAT-11",scaffold:"If the retired population grows relative to the working-age population, fewer people may be earning taxable income while demand for pensions and healthcare increases. The outcome depends on employment, migration and policy.",reforge:{stem:"Which policy could reduce pressure caused by an ageing population?",options:{A:"Encouraging later retirement or higher labour-force participation",B:"Reducing healthcare capacity across the whole of the public sector",C:"Banning pension saving",D:"Deliberately shrinking the size of the working-age population"},correct:"A"}});
replaceGcseEconomicsQuestion("GCSE-ECON-P2-NATIONAL", "GCSE-P2-NAT-12", {id:"GCSE-P2-NAT-12",spec:"GCSE-ECON-P2-NATIONAL",stem:"What does a government budget surplus mean?",options:{A:"Tax revenue is greater than government spending",B:"Imports exceed exports",C:"Household saving exceeds borrowing",D:"Government spending is greater than revenue"},correct:"A",tag:"MC-GCSE-P2-NAT-12",scaffold:"A budget surplus occurs when government revenue exceeds government spending in a period. It is different from a trade surplus, which concerns exports and imports.",reforge:{stem:"A government collects £600 billion and spends £570 billion. It has:",options:{A:"A £30 billion budget surplus",B:"A £30 billion budget deficit",C:"A £1,170 billion trade surplus",D:"Balanced finances"},correct:"A"}});
replaceGcseEconomicsQuestion("GCSE-ECON-P2-GROWTH", "GCSE-P2-GRO-12", {id:"GCSE-P2-GRO-12",spec:"GCSE-ECON-P2-GROWTH",stem:"How might economic growth increase government tax revenue?",options:{A:"Higher incomes and profits can widen the tax base",B:"Growth removes all taxes",C:"Output falls whenever GDP rises",D:"Public services become impossible to fund"},correct:"A",tag:"MC-GCSE-P2-GRO-12",scaffold:"If growth raises employment, incomes and company profits, more taxable activity may increase government receipts. The size of the effect depends on tax rates, distribution and the cause of growth.",reforge:{stem:"Why may growth give a government more scope to fund public services?",options:{A:"Higher taxable incomes can raise receipts",B:"Growth guarantees that no public spending is ever required at all",C:"Economic activity ends",D:"Tax revenue is completely unrelated to the level of national output"},correct:"A"}});

