// Depth expansion: 17 additional specification points per GCSE Psychology bank.
const addPsychDepth = (bankId, spec, prefix, rows) => {
  const answers = rows.map(row => row[1]);
  BANKS[bankId].questions.push(...rows.map((row, index) => {
    const wrongs = [answers[(index + 4) % answers.length], answers[(index + 9) % answers.length], answers[(index + 14) % answers.length]];
    return gcsePsychQuestion(`${prefix}-${String(index + 9).padStart(2,"0")}`, spec, row[0], {A:row[1],B:wrongs[0],C:wrongs[1],D:wrongs[2]}, "A", `This tests the AQA ${spec} knowledge point: ${row[1]}.`, {stem:row[2],options:{A:row[1],B:wrongs[1],C:wrongs[2],D:wrongs[0]},correct:"A"});
  }));
};
