  "GCSE-PSY-MEMORY":["ABCDABCDABCDABCDAB","CADBBCADDBCADBBCAD"],
  "GCSE-PSY-PERCEPTION":["CDABCDABCDABCDABCD","DBACCADBACDBACCAD"],
