// Re-run the length check after all three 40-question expansions have loaded.
for (const bankId of SUBJECTS["gcse-maths"].banks) {
  for (const question of BANKS[bankId].questions) {
    for (const item of [question, question.reforge]) {
      const lengths = Object.fromEntries(Object.entries(item.options).map(([letter, option]) => [letter, String(option).length]));
      const max = Math.max(...Object.values(lengths));
      if (lengths[item.correct] !== max || Object.values(lengths).filter(length => length === max).length !== 1) continue;
      const alternative = Object.keys(item.options).filter(letter => letter !== item.correct).sort((a, b) => lengths[b] - lengths[a])[0];
      while (item.options[alternative].length <= item.options[item.correct].length) item.options[alternative] += " (in this case)";
    }
  }
}

