// Align the Geography questions with the numbered Edexcel 9GE0 key ideas.
// The glossary banks are intentionally grouped by the conceptual sequence of
// each topic; this gives every existing question a real specification point
// without pretending that a generic definition question is a case study.
const geoPoint = code => `edexcel-a-geo-${code}`;
const geoPointForGlossary = {
  "GEO-WATER": [
    ["5.1", 1, 2], ["5.2", 3, 13], ["5.3", 14, 16],
    ["5.4", 17, 21], ["5.7", 22, 24], ["5.8", 25, 29],
    ["5.7", 30, 34], ["5.8", 35, 37]
  ],
  "GEO-CARBON": [
    ["6.1", 1, 6], ["6.2", 7, 10], ["6.3", 11, 18],
    ["6.4", 19, 21], ["6.5", 22, 25], ["6.6", 26, 31],
    ["6.7", 32, 35], ["6.8", 36, 37]
  ],
  "GEO-SUPER": [
    ["7.1", 1, 9], ["7.2", 10, 16], ["7.3", 17, 20],
    ["7.4", 21, 25], ["7.5", 26, 29], ["7.6", 30, 32],
    ["7.8", 33, 35], ["7.9", 36, 37]
  ],
  "GEO-HEALTH": [
    ["8A.1", 1, 7], ["8A.2", 8, 13], ["8A.4", 14, 16],
    ["8A.5", 17, 19], ["8A.6", 20, 23], ["8A.7", 24, 28],
    ["8A.8", 29, 32], ["8A.9", 33, 35], ["8A.12", 36, 37]
  ]
};

const geoDefinitionStemFrames = [
  term => `What is meant by ${term}?`,
  term => `Which description most accurately captures ${term}?`,
  term => `How is ${term} best defined in geography?`,
  term => `A student is revising ${term}. Which note is accurate?`,
  term => `Which option correctly identifies ${term}?`,
  term => `Which explanation gives the meaning of ${term}?`
];

function varyGeoDefinitionStem(question, index) {
  const match = String(question.stem || "").match(/^Which statement best describes (.+)\?$/i);
  if (!match) return;
  const term = match[1];
  question.stem = geoDefinitionStemFrames[index % geoDefinitionStemFrames.length](term);
}

for (const bankId of SUBJECTS["geo"].banks) {
  const bank = BANKS[bankId];
  if (!bank) continue;
  const glossaryRanges = geoPointForGlossary[bankId];
  bank.questions.forEach((question, index) => {
    const number = index + 1;
    if (glossaryRanges) {
      const range = glossaryRanges.find(([, start, end]) => number >= start && number <= end);
      if (range) question.specPointId = geoPoint(range[0]);
    } else {
      const pointSequences = {
        "GEO-TEC": ["1.1", "1.6", "1.3", "1.1", "1.8", "1.2", "1.1", "1.6", "1.6", "1.6", "1.3", "1.5", "1.7", "1.5", "1.8", "1.4"],
        "GEO-COAST": ["2B.1", "2B.2", "2B.3", "2B.4", "2B.10", "2B.5", "2B.6", "2B.7", "2B.8", "2B.9", "2B.10", "2B.12"],
        "GEO-REGEN": ["4A.1", "4A.7", "4A.7", "4A.8", "4A.9", "4A.9", "4A.9", "4A.6", "4A.7", "4A.4", "4A.8", "4A.6"],
        "GEO-P3": ["p3-players", "p3-futures", "p3-futures", "p3-futures", "p3-players", "p3-players", "p3-futures", "p3-players", "p3-players", "p3-players", "p3-attitudes", "p3-futures"]
      }[bankId];
      const broadTopic = pointSequences?.[index];
      if (broadTopic) question.specPointId = geoPoint(broadTopic);
    }
    varyGeoDefinitionStem(question, index);
    if (question.reforge) varyGeoDefinitionStem(question.reforge, index + 2);
  });
}

// Fill the Edexcel B Geography points that are taught at MGSG but were not
// represented in the original banks. These are deliberately application-led
// questions rather than recycled glossary definitions.
const addGeoGapQuestion = (bankId, point, id, stem, options, correct, scaffold, reforgeStem, reforgeOptions, reforgeCorrect) => {
  BANKS[bankId].questions.push({
    id, specPointId: geoPoint(point), spec: `GEO-${bankId.replace("GEO-", "")}`,
    stem, options, correct, tag: `MC-${id}`, scaffold,
    reforge: {stem: reforgeStem, options: reforgeOptions, correct: reforgeCorrect}
  });
};
// Globalisation is one of the school's Year 1 units but had no dedicated
// bank; keep it separate so its questions are not mixed into another topic.
BANKS["GEO-GLOBAL"] = {label:"Globalisation", color:"#0f766e", questions:[]};
SUBJECTS["geo"].banks.push("GEO-GLOBAL");
const geoGapQuestions = [
  ["GEO-TEC", "1.9", "TEC-GAP-01", "Which action is most likely to reduce the impacts of a future earthquake?", {A:"Retrofitting buildings and practising evacuation",B:"Removing all hazard maps from public websites",C:"Building only on steep unstable slopes",D:"Waiting until after the event to plan"}, "A", "Risk reduction combines monitoring, preparedness, land-use planning and buildings designed to withstand shaking.", "Why can retrofitting reduce earthquake risk?", {A:"It makes every earthquake smaller",B:"It strengthens structures so fewer collapse",C:"It prevents plates from moving",D:"It guarantees no injuries occur"}, "B"],
  ["GEO-COAST", "2B.11", "COAST-GAP-01", "Why might a Shoreline Management Plan allow some coastal flooding?", {A:"Protection costs may exceed the value of land",B:"Flooding always improves every local economy",C:"Sea level is falling along all British coasts",D:"Hard engineering has no environmental effects"}, "A", "Coastal management balances risk, cost, environmental value and the needs of different communities over time.", "What is a likely trade-off of managed realignment?", {A:"It can create habitat but may remove farmland",B:"It prevents all erosion along the coastline",C:"It guarantees higher land values inland",D:"It removes the need for flood warnings"}, "A"],
  ["GEO-WATER", "5.5", "WATER-GAP-01", "How can urban growth alter a drainage basin's response to rainfall?", {A:"More impermeable surfaces can increase rapid runoff",B:"More roads always increase infiltration into soil",C:"Urban growth stops precipitation reaching the basin",D:"Buildings remove the need for storm drains"}, "A", "Urbanisation can reduce infiltration and interception while increasing surface runoff, so peak discharge may rise.", "Which measure can reduce urban flood risk?", {A:"Permeable paving and sustainable drainage",B:"Covering every open space with concrete",C:"Removing wetlands from the floodplain",D:"Straightening every small stream"}, "A"],
  ["GEO-WATER", "5.6", "WATER-GAP-02", "Why can water insecurity persist even where rainfall is plentiful?", {A:"Poor infrastructure may limit safe access",B:"Rainfall automatically becomes drinking water",C:"High rainfall prevents any contamination",D:"Water demand is identical in every place"}, "A", "Water security depends on availability, quality, affordability, infrastructure and governance, not rainfall alone.", "Which factor is a human cause of water insecurity?", {A:"Leaking pipes and weak water governance",B:"A reliable treatment network",C:"Low demand during a wet season",D:"Protected groundwater recharge"}, "A"],
  ["GEO-CARBON", "6.9", "CARBON-GAP-01", "Which strategy most directly reduces carbon emissions from electricity generation?", {A:"Replacing coal power with low-carbon generation",B:"Increasing energy waste in older buildings",C:"Expanding dependence on imported coal",D:"Removing monitoring of industrial emissions"}, "A", "Decarbonisation reduces emissions through cleaner generation, efficiency, electrification and changes in demand.", "Why is energy efficiency part of decarbonisation?", {A:"It provides the same service using less energy",B:"It increases energy demand for every household",C:"It makes fossil fuels renewable",D:"It removes the need for any electricity"}, "A"],
  ["GEO-SUPER", "7.7", "SUPER-GAP-01", "What is a possible consequence of a shift towards a multipolar world?", {A:"More states may influence global decisions",B:"One state automatically controls every region",C:"International trade becomes impossible",D:"All military alliances disappear"}, "A", "A multipolar system distributes influence among several major powers, which can create cooperation and competition.", "Which development could strengthen an emerging power's influence?", {A:"Growth in its economy and diplomatic networks",B:"A permanent loss of trade and investment",C:"The closure of all international institutions",D:"The removal of its technological capacity"}, "A"],
  ["GEO-HEALTH", "8A.3", "HEALTH-GAP-01", "Why can health be considered a human-rights issue?", {A:"Access to essential care affects dignity and survival",B:"Health outcomes are determined only by genetics",C:"Rights apply only to people in wealthy countries",D:"Healthcare has no connection with inequality"}, "A", "Geography links health to rights, social determinants, access to services and the ability to live with dignity.", "Which example shows a health inequality?", {A:"Rural patients travel farther for specialist care",B:"A national service is free at the point of use",C:"A clinic publishes its opening hours",D:"A hospital trains additional nurses"}, "A"],
  ["GEO-HEALTH", "8A.10", "HEALTH-GAP-02", "What should be used to judge whether a health intervention worked?", {A:"Evidence of outcomes and unintended effects",B:"The size of the launch event alone",C:"The number of posters printed",D:"The popularity of its advertising"}, "A", "Evaluation should compare intended outcomes with evidence such as morbidity, mortality, access, cost and unintended consequences.", "Why might a vaccination programme have limited impact?", {A:"Low trust or poor access may reduce uptake",B:"Vaccines always spread the disease targeted",C:"Health systems cannot collect coverage data",D:"Prevention never changes population health"}, "A"],
  ["GEO-HEALTH", "8A.11", "HEALTH-GAP-03", "Why might an intervention designed for one place fail elsewhere?", {A:"Local culture, resources and needs may differ",B:"Health interventions work identically everywhere",C:"Local communities cannot affect health outcomes",D:"Geography has no role in disease prevention"}, "A", "Interventions are more effective when they are appropriate to local conditions and involve affected communities.", "Which feature makes a health intervention more sustainable?", {A:"Local staff can maintain it after funding ends",B:"It depends on imported experts indefinitely",C:"It ignores local beliefs and practices",D:"It measures success only once"}, "A"],
  ["GEO-REGEN", "4A.2", "REGEN-GAP-01", "Which evidence best shows whether regeneration changed a place for existing residents?", {A:"Resident surveys alongside employment and housing data",B:"A single promotional photograph of the scheme",C:"The height of a new landmark alone",D:"The developer's original press release"}, "A", "Regeneration should be assessed using economic, social, environmental and lived-experience evidence at an appropriate scale.", "Why combine quantitative and qualitative evidence?", {A:"It links measurable change with residents' experiences",B:"It removes the need to check data quality",C:"It guarantees every stakeholder agrees",D:"It makes comparison between places impossible"}, "A"],
  ["GEO-REGEN", "4A.3", "REGEN-GAP-02", "Why can regeneration create conflict between stakeholders?", {A:"Different groups may gain or lose from change",B:"All stakeholders have identical priorities",C:"Residents never influence planning decisions",D:"Developers cannot benefit from new investment"}, "A", "Stakeholder conflict reflects competing views about costs, benefits, identity, housing, jobs and environmental quality.", "Which group might oppose a profitable redevelopment?", {A:"Residents worried about displacement",B:"A retailer expecting more customers",C:"A council receiving new tax revenue",D:"A developer seeking higher land value"}, "A"],
  ["GEO-REGEN", "4A.5", "REGEN-GAP-03", "Which outcome could indicate that regeneration has increased inequality?", {A:"Property values rise while low-income residents are displaced",B:"Local residents gain affordable homes and secure jobs",C:"Public transport becomes cheaper and more reliable",D:"Vacant land becomes a community space"}, "A", "A project can improve an area's image and investment while worsening affordability or access for some groups.", "What policy could reduce displacement during regeneration?", {A:"Including affordable housing and tenant protection",B:"Removing all planning conditions",C:"Replacing community facilities with luxury retail",D:"Basing decisions only on visitor numbers"}, "A"],
  ["GEO-GLOBAL", "3.1", "GLOBAL-GAP-01", "Which process has most accelerated globalisation since the late twentieth century?", {A:"Faster communication and transport networks",B:"Reduced international contact between businesses",C:"The end of all cross-border investment",D:"A universal fall in internet access"}, "A", "Technological change has lowered the time and cost of moving information, people, goods and services.", "How can digital communication support globalisation?", {A:"It links firms and consumers across borders",B:"It prevents international collaboration",C:"It removes the need for trade routes",D:"It makes all places economically identical"}, "A"],
  ["GEO-GLOBAL", "3.2", "GLOBAL-GAP-02", "What is a global production network?", {A:"Production stages spread across several countries",B:"A factory supplying only its local village",C:"A government budget for public services",D:"A single firm with no overseas links"}, "A", "Design, finance, components, assembly and sales may be organised across different places in a global production network.", "Why might a firm distribute production internationally?", {A:"To access skills, markets or lower costs",B:"To eliminate all supply-chain risk",C:"To avoid using transport networks",D:"To prevent any foreign investment"}, "A"],
  ["GEO-GLOBAL", "3.3", "GLOBAL-GAP-03", "How can a transnational corporation influence a host country?", {A:"It can create jobs and reshape local supply chains",B:"It has no effect outside its headquarters",C:"It can never move investment between countries",D:"It is legally identical to a local household"}, "A", "TNC impacts can include employment, tax, technology transfer, environmental pressure and bargaining power over governments.", "Which is a possible criticism of TNC investment?", {A:"Profits may leave while local environmental costs remain",B:"It always prevents workers receiving wages",C:"It cannot change local land use",D:"It removes every domestic business"}, "A"],
  ["GEO-GLOBAL", "3.4", "GLOBAL-GAP-04", "Why might a country attract foreign direct investment?", {A:"Investment can bring jobs, capital and technology",B:"Investment always reduces tax revenue",C:"Foreign firms cannot build local facilities",D:"FDI prevents exports from increasing"}, "A", "FDI may support development but outcomes depend on regulation, linkages, wages, taxation and environmental safeguards.", "Which policy can improve the local benefits of FDI?", {A:"Training programmes and stronger local supply links",B:"Removing all labour and environmental standards",C:"Banning local firms from supplying investors",D:"Allowing profits to leave without any taxation"}, "A"],
  ["GEO-GLOBAL", "3.5", "GLOBAL-GAP-05", "What is the main purpose of a trade bloc?", {A:"To reduce trade barriers between member states",B:"To prevent all movement of services",C:"To replace every national government",D:"To stop member states trading with neighbours"}, "A", "Trade blocs can increase market access while also creating different relationships with non-members.", "What is a possible disadvantage of joining a trade bloc?", {A:"Some national policy choices may be constrained",B:"Member states cannot trade with each other",C:"All domestic industries automatically disappear",D:"Transport links are no longer needed"}, "A"],
  ["GEO-GLOBAL", "3.6", "GLOBAL-GAP-06", "How can globalisation affect employment unevenly?", {A:"Some regions gain jobs while others lose industries",B:"Every worker receives the same wage increase",C:"Jobs cannot move between countries",D:"Global trade affects consumers but never workers"}, "A", "Globalisation creates opportunities and vulnerabilities depending on skills, sector, location, infrastructure and government policy.", "Which worker is most exposed to offshoring?", {A:"A worker in a routine service that can be moved abroad",B:"A worker providing a place-specific emergency service",C:"A farmer selling only at a local market",D:"A teacher working with one local class"}, "A"],
  ["GEO-GLOBAL", "3.7", "GLOBAL-GAP-07", "Why do governments regulate global economic activity?", {A:"To manage risks involving workers, consumers and environments",B:"To guarantee that every firm earns the same profit",C:"To prevent all international investment",D:"To make global supply chains disappear"}, "A", "Governments use standards, taxes, planning and agreements to balance growth with social and environmental goals.", "Which measure could improve supply-chain accountability?", {A:"Requiring firms to report labour and environmental impacts",B:"Removing all disclosure requirements",C:"Banning independent inspections",D:"Allowing firms to set every rule privately"}, "A"],
  ["GEO-GLOBAL", "3.8", "GLOBAL-GAP-08", "What does global inequality describe?", {A:"Unequal wealth, power and opportunities between places",B:"Identical living standards in every country",C:"Differences in weather between two cities",D:"A country's total population size alone"}, "A", "Global inequality includes income, health, education, technology, political power and access to resources.", "Which factor can reproduce global inequality?", {A:"Unequal access to finance, education and technology",B:"Universal access to high-speed internet",C:"Equal bargaining power in trade",D:"Shared control of global institutions"}, "A"],
  ["GEO-GLOBAL", "3.9", "GLOBAL-GAP-09", "Why is globalisation described as dynamic rather than complete?", {A:"Technology, policy and power continue to reshape connections",B:"All global connections stopped developing",C:"Only physical goods can cross borders",D:"Every place benefits in exactly the same way"}, "A", "Globalisation changes as technologies, trade rules, crises, conflicts and patterns of power change.", "Which event could temporarily reduce global connectivity?", {A:"A pandemic disrupting travel and supply chains",B:"A faster undersea cable network",C:"A fall in the cost of shipping",D:"A new cross-border trade agreement"}, "A"]
];
for (const row of geoGapQuestions) addGeoGapQuestion(...row);
rebalanceGeoYear2(["GEO-TEC","GEO-COAST","GEO-REGEN","GEO-WATER","GEO-CARBON","GEO-SUPER","GEO-HEALTH"]);

// ===== A LEVEL PSYCHOLOGY (AQA 7182) PAPER 3 OPTION: FORENSIC PSYCHOLOGY =====
BANKS["PSY-FOR"] = {
  label: "Forensic Psychology",
  color: "#831843",
  questions: [
    {
      id:"FOR-01",stem:"The top-down approach to offender profiling was developed by:",
      options:{A:"The FBI, from interviews with 36 convicted sexually motivated murderers",B:"David Canter, working from statistical analysis of crime scene data",C:"Cesare Lombroso, from measurements of the skulls of convicted criminals",D:"Hans Eysenck, from questionnaires measuring criminal personality traits"},correct:"A",tag:"MC-FOR-PROFILE",
      scaffold:"The FBI's Behavioral Science Unit interviewed 36 sexually motivated murderers, including Bundy and Berkowitz, and concluded that crime scenes fall into two categories reflecting the offender. Organised offenders plan, target a stranger, control the victim, leave little evidence, and tend to be intelligent, socially competent and in skilled work. Disorganised offenders act spontaneously with little planning, leave the body and evidence at the scene, and tend to be lower in intelligence, socially isolated and unskilled. The profiler matches the scene to a category, then infers characteristics. It is called top-down because it starts from pre-existing typologies and fits the case to them.",
      reforge:{stem:"Why is the FBI approach described as 'top-down'?",options:{A:"It starts from pre-existing typologies and fits the case to them",B:"It begins with statistical analysis of the crime scene evidence",C:"It works upwards from the geographical location of the offences",D:"It is applied only to offenders at the top of criminal organisations"},correct:"A"}
    },
    {
      id:"FOR-02",stem:"Which is the strongest criticism of the organised/disorganised typology?",
      options:{A:"It has been applied quite successfully to every single category of criminal offence",B:"The original sample was far too large to analyse in any detail",C:"The sample was small, self-selecting and offenders may not tell the truth",D:"It relies entirely on statistical analysis rather than on interviews"},correct:"C",tag:"MC-FOR-PROFILE",
      scaffold:"The evidential base is weak: 36 offenders is a small, self-selecting sample of convicted, and therefore caught, killers, so it may not represent offenders generally — and serial killers are manipulative, so self-report is questionable. Canter's smallest space analysis of 100 US murders found the organised type existed but the disorganised features did not form a distinct pattern, suggesting the dichotomy is too simple; many offenders show both. The approach is also limited to crimes revealing psychopathology, such as sexual assault and murder, and cannot help with burglary or fraud. Balance with the acknowledgement that Copson found 83% of officers thought profiling useful, though only 3% said it identified the offender.",
      reforge:{stem:"What did Canter's smallest space analysis suggest about the typology?",options:{A:"Both categories were confirmed as entirely separate types",B:"Disorganised offenders were far more common than organised ones",C:"The typology applies to all types of criminal offence equally",D:"Organised features clustered, but disorganised ones did not"},correct:"D"}
    },
    {
      id:"FOR-03",stem:"Canter's bottom-up approach differs from the top-down approach because it:",
      options:{A:"Generates a profile from statistical analysis of the specific evidence",B:"Relies on the profiler's own professional intuition and prior experience",C:"Assigns offenders to one of two pre-existing behavioural categories",D:"Can only be applied to crimes involving serious sexual violence"},correct:"A",tag:"MC-FOR-PROFILE",
      scaffold:"The bottom-up approach is data-driven: it builds the profile up from the evidence in this particular case rather than fitting the case into a category. Investigative psychology applies statistical analysis to identify patterns across offences, using concepts such as interpersonal coherence — offenders behave with victims as they do in ordinary life — the significance of time and place, and forensic awareness suggesting previous police contact. Because it is grounded in statistics rather than typologies, it applies to a much wider range of crimes including burglary, and it is more scientific and objective. That contrast between intuitive typology and empirical analysis is the standard comparison question.",
      reforge:{stem:"What does 'interpersonal coherence' mean in investigative psychology?",options:{A:"Offenders behave towards victims as they do in everyday life",B:"All offenders in a series must be working together in a group",C:"Crime scenes always cohere into one of two clear categories",D:"The offender lives close to the centre of the offence locations"},correct:"A"}
    },
    {
      id:"FOR-04",stem:"Canter's circle theory of geographical profiling distinguishes between:",
      options:{A:"Organised and disorganised offenders based on crime scene evidence",B:"Extravert and introvert offenders based on personality questionnaires",C:"Somatotypes identified from the physical build of the offender",D:"The marauder, offending near home, and the commuter, travelling away"},correct:"D",tag:"MC-FOR-GEO",
      scaffold:"Geographical profiling assumes offenders reveal themselves through where they offend. Canter's circle theory plots the offences and draws a circle enclosing them: the marauder operates from a home base within that circle, so the spatial pattern points to their base, while the commuter travels away from home to offend, so the circle does not contain their residence. Underlying this is the least effort principle and a mental map of familiar areas. Lundrigan and Canter's analysis of 120 US murders found the marauder pattern common, with disposal sites forming a centre-of-gravity around the base. The limitation is that it requires a series of offences and accurate, complete police data.",
      reforge:{stem:"What practical limitation applies to geographical profiling?",options:{A:"It can be used only for a single, isolated offence",B:"It requires a series of linked offences and accurate data",C:"It works only for those offences committed indoors and at night",D:"It cannot be combined with any other profiling method"},correct:"B"}
    },
    {
      id:"FOR-05",stem:"Lombroso's atavistic form theory proposed that criminals:",
      options:{A:"Learn criminal behaviour through association with delinquent peers",B:"Have an overactive superego producing an unconscious need for punishment",C:"Are evolutionary throwbacks identifiable by distinct physical features",D:"Inherit a specific gene that directly determines violent offending"},correct:"C",tag:"MC-FOR-BIO",
      scaffold:"Lombroso argued in 1876 that criminals were a separate species, biologically primitive and unable to adjust to civilised society, so offending was innate rather than chosen. He catalogued supposed atavistic features from examining 383 dead and 3,839 living criminals — a strong jaw, high cheekbones, extra nipples, toes or fingers, dark skin — and assigned different features to different crime types. His genuine contribution was to shift criminology towards scientific study of the offender, making him the father of modern criminology. But the theory is scientifically discredited and, in classing some ethnic groups as atavistic, overtly racist; he also used no control group.",
      reforge:{stem:"What is the most serious methodological flaw in Lombroso's research?",options:{A:"He examined only offenders who had already been released",B:"He used exclusively female participants in his research",C:"His sample of criminals was extremely small in size",D:"He used no non-criminal control group for comparison"},correct:"D"}
    },
    {
      id:"FOR-06",stem:"Research into the MAOA gene suggests that it is associated with offending because it:",
      options:{A:"Directly causes offending in every single individual who inherits the variant",B:"Regulates serotonin, and a low-activity variant is linked to aggression",C:"Produces the physical atavistic features Lombroso originally described",D:"Determines whether a person will develop an extravert personality type"},correct:"B",tag:"MC-FOR-BIO",
      scaffold:"MAOA produces an enzyme that breaks down neurotransmitters including serotonin; the low-activity 'warrior gene' variant is associated with raised aggression. Brunner's study of a Dutch family with a history of violent offending found this variant in the men involved. Critically, Caspi found the gene alone did not predict antisocial behaviour — 85% of men with the low-activity variant who had also been maltreated as children showed antisocial outcomes, but those with the variant and no maltreatment largely did not. That is a diathesis-stress finding and the point examiners want: genes create predisposition, environment triggers it, so biological determinism alone is inadequate.",
      reforge:{stem:"What did Caspi's findings suggest about the MAOA gene?",options:{A:"The gene alone determines antisocial behaviour completely",B:"Childhood maltreatment has no effect on any outcome",C:"Its effect appears only when combined with childhood maltreatment",D:"The gene protects against the development of antisocial behaviour"},correct:"C"}
    },
    {
      id:"FOR-07",stem:"Raine's brain imaging research on murderers pleading not guilty by reason of insanity found:",
      options:{A:"Completely identical brain activity to matched non-offender control participants",B:"Increased activity throughout the whole of the cerebral cortex",C:"Damage confined entirely to the occipital lobe and visual cortex",D:"Reduced activity in the prefrontal cortex, which regulates impulse control"},correct:"D",tag:"MC-FOR-BIO",
      scaffold:"Raine used PET scans to compare 41 murderers pleading NGRI with matched controls and found reduced glucose metabolism in the prefrontal cortex, the region governing impulse control, planning and the regulation of aggression, along with abnormalities in the amygdala and limbic system. This supports a neural explanation of violent offending, and links to research showing reduced grey matter in the prefrontal cortex of people with antisocial personality disorder. Evaluate carefully: the sample is a very specific group of offenders, causation is uncertain since a lifestyle of violence and head injury may cause the differences, and it raises serious questions about legal responsibility.",
      reforge:{stem:"Why must Raine's findings be interpreted cautiously?",options:{A:"PET scans simply cannot detect any activity in the prefrontal cortex",B:"Brain differences may result from the offending lifestyle itself",C:"No control group was included anywhere in the study",D:"The study was conducted entirely on non-human animals"},correct:"B"}
    },
    {
      id:"FOR-08",stem:"In Eysenck's theory, the criminal personality is characterised by high scores on:",
      options:{A:"Extraversion, neuroticism and psychoticism together",B:"Introversion, emotional stability and high agreeableness",C:"Openness, conscientiousness and agreeableness combined",D:"Only psychoticism, with no role for any other dimension"},correct:"A",tag:"MC-FOR-PSYCH",
      scaffold:"Eysenck proposed three dimensions measured by the EPQ. Extraverts have an underactive reticular activating system, so they seek stimulation and take risks. Neurotics have a reactive sympathetic nervous system, making them jumpy and unpredictable. High psychoticism is associated with being cold, unemotional and prone to aggression. Crucially he added a socialisation element: because extraverts and neurotics condition poorly, they do not readily learn to associate antisocial behaviour with anxiety, so conscience develops weakly. Evaluate with Farrington, who found offenders scored high on P and N but not consistently on E, and with the criticism that a single criminal type is too simplistic.",
      reforge:{stem:"Why did Eysenck argue that extraverts are more likely to offend?",options:{A:"They have an overactive nervous system that inhibits nearly all action",B:"They inherit the atavistic features that Lombroso described",C:"They possess an unusually harsh and punitive superego",D:"They condition poorly, so conscience is learned less effectively"},correct:"D"}
    },
    {
      id:"FOR-09",stem:"Kohlberg argued that offenders are more likely to reason at which level of moral development?",
      options:{A:"The post-conventional level, guided by abstract universal principles",B:"The pre-conventional level, focused on avoiding punishment and gaining reward",C:"The conventional level, which is concerned with maintaining social approval and law",D:"They show no identifiable pattern of moral reasoning at all"},correct:"B",tag:"MC-FOR-COG",
      scaffold:"Kohlberg's three levels, each with two stages, run from pre-conventional (avoid punishment, gain personal reward), through conventional (gain approval, maintain law and order), to post-conventional (social contract, universal ethical principles). Offenders are more likely to reason at the pre-conventional level, so a crime is judged worthwhile if the reward is high and detection unlikely — the calculation is about consequences to the self rather than the rights of others. Palmer and Hollin compared 332 non-offenders with 126 convicted offenders and found the offenders showed less mature moral reasoning, supporting the claim. Note that reasoning is not the same as behaviour, which weakens the link.",
      reforge:{stem:"What did Palmer and Hollin's comparison find?",options:{A:"Offenders showed more mature moral reasoning than non-offenders",B:"Both groups reasoned at exactly the same moral level",C:"Convicted offenders showed less mature moral reasoning",D:"Moral reasoning could not be measured in either group"},correct:"C"}
    },
    {
      id:"FOR-10",stem:"A convicted offender claims the victim 'was asking for it by walking there at night'. This is an example of:",
      options:{A:"Minimalisation, downplaying the seriousness of the offence committed",B:"Differential association with a criminal peer group over time",C:"Hostile attribution bias, misreading ambiguous cues as threatening",D:"An overactive superego generating unconscious guilt and a need to be caught"},correct:"A",tag:"MC-FOR-COG",
      scaffold:"Two cognitive distortions are examined. Minimalisation downplays the seriousness or reframes responsibility — burglars describing themselves as 'doing a job', or sex offenders blaming the victim's behaviour, which Barbaree found in 54% of convicted rapists who denied or minimised the harm caused. Hostile attribution bias is different: it is misreading ambiguous or neutral cues, such as a glance, as threatening, which Schönenberg and Justye demonstrated by showing violent offenders were more likely to interpret neutral faces as angry. Both are cognitive rather than biological, and both are addressed in treatment through CBT-based anger management and offending behaviour programmes.",
      reforge:{stem:"What did Schönenberg and Justye's study of violent offenders demonstrate?",options:{A:"Offenders were more likely to read neutral faces as angry",B:"Offenders could not recognise any facial expressions at all",C:"Offenders minimised the seriousness of all their offences",D:"Offenders showed unusually accurate perception of emotion"},correct:"A"}
    },
    {
      id:"FOR-11",stem:"Sutherland's differential association theory explains offending as:",
      options:{A:"The result of an inherited predisposition towards antisocial behaviour",B:"An expression of unresolved unconscious conflict from early childhood",C:"A direct consequence of reduced activity in the prefrontal cortex of the brain",D:"Learned through interaction, when pro-crime attitudes outweigh anti-crime ones"},correct:"D",tag:"MC-FOR-DIFF",
      scaffold:"Sutherland argued crime is learned like any other behaviour, through interaction within intimate personal groups. The individual acquires attitudes towards the law and specific techniques for committing offences, and offends when pro-criminal definitions outweigh anti-criminal ones — a claim he suggested could in principle be mathematically calculated. Its strengths are real: it shifted explanation away from biological and individualistic accounts towards social factors, it explains crime across all social classes including white-collar crime, and it accounts for reoffending after imprisonment, where offenders are surrounded by pro-criminal attitudes. The weaknesses are that the variables are hard to operationalise and it risks stereotyping those from high-crime backgrounds.",
      reforge:{stem:"Which observation does differential association explain particularly well?",options:{A:"Why offending correlates with reduced prefrontal cortex activity",B:"Why recidivism is high after a period spent in prison",C:"Why some offenders possess distinct physical characteristics",D:"Why offenders score highly on measures of neuroticism"},correct:"B"}
    },
    {
      id:"FOR-12",stem:"Blackburn's psychodynamic explanation proposes that offending can result from:",
      options:{A:"A deviant superego, which may be weak, over-harsh or deviant",B:"Poor classical conditioning of the fear response in childhood",C:"Attributing hostile intent to other people's neutral behaviour",D:"Learning pro-criminal attitudes from an intimate peer group"},correct:"A",tag:"MC-FOR-PSYCH",
      scaffold:"Blackburn identified three superego problems. A weak superego, if the same-sex parent is absent during the phallic stage, leaves the id unchecked so immoral behaviour is more likely. A deviant superego, internalised from a criminal same-sex parent, means the person follows deviant standards without guilt. An over-harsh superego produces overwhelming unconscious guilt and a need for punishment, so the person offends in order to be caught. Evaluate with the standard objections: the concepts are unfalsifiable and unscientific, the account is gender-biased since it implies women should be less moral, and Bowlby's related maternal deprivation work has serious methodological problems.",
      reforge:{stem:"Why is the psychodynamic explanation of offending widely criticised?",options:{A:"It has generated no useful treatments for offending behaviour",B:"It relies entirely on brain imaging evidence",C:"Its concepts are unconscious and therefore unfalsifiable",D:"It applies only to offenders under the age of eighteen"},correct:"C"}
    },
    {
      id:"FOR-13",stem:"Which is NOT one of the recognised aims of custodial sentencing?",
      options:{A:"Deterrence, discouraging the individual and the wider public from offending",B:"Rehabilitation, so the offender can return to society better able to comply",C:"Incapacitation, protecting the public by removing the offender from society",D:"Compensation, requiring the offender to repay the victim financially"},correct:"D",tag:"MC-FOR-CUSTODY",
      scaffold:"The four recognised aims are deterrence, both individual and general; incapacitation, protecting the public; retribution, society exacting revenge proportionate to the crime; and rehabilitation, reforming the offender. Compensation is a feature of restorative justice rather than custodial sentencing. Learn the aims alongside the psychological effects that undermine them: high suicide rates, self-harm, depression, institutionalisation, and prisonisation, where inmates adopt an inmate code. Recidivism in the UK runs at around 45% within a year, and differential association explains why — prison places offenders among pro-criminal peers, so it may function as a university of crime.",
      reforge:{stem:"Which psychological effect describes inmates adopting the norms of prison life?",options:{A:"Prisonisation, adopting an inmate code and prison culture",B:"Deindividuation caused by the wearing of a prison uniform",C:"Minimalisation of the seriousness of their offence",D:"Hostile attribution bias towards other inmates"},correct:"A"}
    },
    {
      id:"FOR-14",stem:"Behaviour modification in custody is based on which psychological principle?",
      options:{A:"Classical conditioning, pairing offending with an unpleasant stimulus",B:"Operant conditioning, reinforcing desirable behaviour with tokens",C:"Social learning, having offenders observe and imitate prosocial models",D:"Cognitive restructuring of the offender's irrational belief system"},correct:"B",tag:"MC-FOR-TREAT",
      scaffold:"Token economies apply operant conditioning directly: desirable behaviours are operationalised in advance, and inmates earn tokens — secondary reinforcers — which are exchanged for privileges such as phone calls or extra visits. Effective implementation requires consistency among all staff and immediate reinforcement. Hobbs and Holt found improvements in behaviour among young offenders. The critical limitation is that gains rarely persist after release, because the reinforcement schedule ends and the behaviour extinguishes — it changes behaviour without changing thinking. There are also ethical objections about withdrawing basic entitlements, and it may simply produce superficial compliance for as long as it pays.",
      reforge:{stem:"Why do the effects of token economies rarely persist after release?",options:{A:"Offenders simply forget the behaviours that they learned in custody",B:"Token economies are illegal outside the prison system",C:"Reinforcement ends outside prison, so the behaviour extinguishes",D:"The tokens themselves have real monetary value outside"},correct:"C"}
    },
    {
      id:"FOR-15",stem:"Anger management programmes typically follow which three stages?",
      options:{A:"Assessment, medication and then supervised release into the community",B:"Confrontation, apology and financial compensation to the victim",C:"Cognitive preparation, skills acquisition, and application practice",D:"Conceptualisation, token reinforcement and then gradual withdrawal"},correct:"C",tag:"MC-FOR-TREAT",
      scaffold:"Anger management is a form of stress inoculation training applied to offending, and the three stages mirror it. Cognitive preparation: the offender reflects on past experience, identifies triggers and recognises how they interpret situations, often revealing hostile attribution bias. Skills acquisition: they learn cognitive techniques such as positive self-talk, behavioural techniques such as assertiveness, and physiological techniques such as relaxation. Application practice: they rehearse in controlled role play requiring genuine commitment, with the therapist deliberately provoking them. Keen found improved self-control, but Blackburn notes little evidence of reduced long-term recidivism, and role play may not transfer to real provocation.",
      reforge:{stem:"What is the main limitation of anger management programmes?",options:{A:"They cannot be delivered within a prison environment",B:"They rely entirely upon the use of prescribed medication",C:"They address behaviour without any cognitive element",D:"Improvements may not transfer to real-world provocation"},correct:"D"}
    },
    {
      id:"FOR-16",stem:"Restorative justice programmes are characterised by:",
      options:{A:"Extending the custodial sentence to increase its deterrent effect",B:"A supervised meeting in which the offender confronts the harm caused",C:"Reinforcing prosocial behaviour with tokens exchangeable for privileges",D:"Teaching the offender relaxation and positive self-talk techniques"},correct:"B",tag:"MC-FOR-TREAT",
      scaffold:"Restorative justice shifts the focus from punishment to repair, treating crime as harm done to a person rather than to the state. A trained mediator supervises a meeting where the victim explains the impact and the offender must face it; the process is voluntary for both, and may include financial compensation or reparative work. The evidence is strong: the UK Restorative Justice Council reported 85% victim satisfaction, and Strang's meta-analysis found reduced reoffending compared with custody. Evaluate with the caveats — high dropout rates, the risk that offenders participate to reduce their sentence rather than from remorse, and the possibility of re-traumatising a victim if handled badly.",
      reforge:{stem:"What is a significant risk of restorative justice for victims?",options:{A:"Victims are legally required to attend the meeting",B:"Victims must pay the costs of the mediation process",C:"A poorly handled meeting may re-traumatise the victim",D:"Victims are never informed of the offender's identity"},correct:"C"}
    },
    {
      id:"FOR-17",stem:"Which is a limitation of using official statistics to measure crime?",
      options:{A:"They include every offence committed, whether reported or not",B:"They are collected only once every ten years in the United Kingdom",C:"They measure victims' experiences rather than recorded offences",D:"The dark figure of unreported and unrecorded crime is excluded"},correct:"D",tag:"MC-FOR-MEASURE",
      scaffold:"Official statistics record only crimes reported to and recorded by the police, so they miss the dark figure — offences not reported because the victim feels ashamed, distrusts the police or considers the matter trivial, and offences reported but not recorded because of police discretion or recording practice. This makes them a social construction reflecting policing priorities as much as criminal behaviour, and it particularly distorts sexual offences and domestic abuse. Alternatives each have their own problems: victim surveys such as the Crime Survey for England and Wales capture unreported crime but rely on memory and exclude victimless crime, while offender surveys rely on honest self-report.",
      reforge:{stem:"What advantage does the Crime Survey for England and Wales have?",options:{A:"It captures crimes that were never reported to the police",B:"It includes every victimless crime committed in the country",C:"It relies on police recording practice for its accuracy",D:"It records only those offences resulting in a conviction"},correct:"A"}
    },
    {
      id:"FOR-18",stem:"A profiler concludes an offender is likely to live near the cluster of offence locations. This uses:",
      options:{A:"The organised and disorganised typology developed by the FBI",B:"Eysenck's personality dimensions measured by questionnaire",C:"Geographical profiling, based on the marauder spatial pattern",D:"Differential association within the offender's local peer group"},correct:"C",tag:"MC-FOR-GEO",
      scaffold:"This is the marauder pattern from Canter's circle theory: offences cluster around a home base because offenders operate within a familiar mental map and follow the least effort principle, choosing opportunities close to home while avoiding the immediate vicinity where they might be recognised — the buffer zone. Software such as Rossmo's Criminal Geographic Targeting formalises this into a probability map. It is a bottom-up technique because it derives conclusions from the specific data of this case rather than fitting the offender into a pre-existing type, and it has the practical advantage of narrowing a search area, which is directly useful to an investigation.",
      reforge:{stem:"What is the 'buffer zone' in geographical profiling?",options:{A:"The maximum distance an offender will travel to offend",B:"The area immediately around home, avoided to reduce recognition",C:"The time gap between successive offences in a series",D:"The circle that is drawn to enclose all known offence locations"},correct:"B"}
    },
    {
      id:"FOR-19",stem:"Which finding weakens Eysenck's theory of the criminal personality?",
      options:{A:"Offenders consistently score highly on all three of his dimensions",B:"Personality cannot be measured by any questionnaire method",C:"Farrington found offenders high on P and N but not on extraversion",D:"Eysenck never developed any measure of his personality dimensions"},correct:"C",tag:"MC-FOR-PSYCH",
      scaffold:"Farrington's meta-analysis found offenders scored highly on psychoticism and neuroticism but not consistently on extraversion, which undermines the composite criminal personality. Deeper criticisms follow: the idea of a single criminal type is too simplistic for the enormous variety of offending, and Moffitt's distinction between adolescence-limited and life-course-persistent offenders shows different pathways requiring different explanations. Measuring personality by self-report questionnaire assumes it is a stable, measurable entity, which situationists dispute. There is also cultural variation — Bartol found Hispanic and African-American offenders were less extravert than controls. The theory's strength is that it usefully combined biological and socialisation elements.",
      reforge:{stem:"What distinction did Moffitt draw between types of offender?",options:{A:"Organised offenders and disorganised offenders",B:"Marauders who stay near home and commuters who travel",C:"Offenders with weak superegos and those with over-harsh ones",D:"Adolescence-limited and life-course-persistent offenders"},correct:"D"}
    },
    {
      id:"FOR-20",stem:"Which explanation of offending is most clearly supported by high recidivism rates after imprisonment?",
      options:{A:"Differential association, as prison exposes offenders to pro-crime attitudes",B:"Lombroso's atavistic form, since physical features do not change in custody",C:"The genetic explanation, since inherited genes are unaltered by imprisonment",D:"Geographical profiling, since offenders return to their original home area"},correct:"A",tag:"MC-FOR-DIFF",
      scaffold:"UK recidivism runs at roughly 45% within a year of release, and differential association offers a direct account: prison concentrates offenders together, so inmates learn both pro-criminal attitudes and specific techniques from more experienced peers — the university of crime effect. This is a powerful argument against custodial sentencing as rehabilitation and a strong case for community alternatives and restorative justice. Note that other explanations can accommodate recidivism too, so the question is which explains it most directly: genetic and atavistic accounts predict persistence but say nothing about why prison specifically fails, whereas differential association identifies the mechanism.",
      reforge:{stem:"What policy conclusion follows most directly from this evidence?",options:{A:"Custodial sentences should be substantially lengthened",B:"Community alternatives may rehabilitate more effectively",C:"Offenders should be assessed for atavistic physical features",D:"Prisons should house more offenders in each individual cell"},correct:"B"}
    },
    {
      id:"FOR-21",stem:"Which ethical issue arises from biological explanations of offending?",
      options:{A:"They cannot be tested using any recognised scientific method",B:"They deny that any environmental factors have the slightest influence at all",C:"They may reduce personal responsibility and justify pre-emptive control",D:"They have never been used in any legal proceedings anywhere"},correct:"C",tag:"MC-FOR-ETHICS",
      scaffold:"If offending is caused by genes or brain structure, the offender did not freely choose it, which sits awkwardly with a legal system built on responsibility — and MAOA evidence has been introduced in court in mitigation, notably in Italian cases where sentences were reduced. The more troubling implication is pre-emptive: if a biological marker predicts offending, there is pressure to screen and intervene before any crime, which raises civil liberties concerns and echoes the eugenic misuse of early criminology. This is prime material for the socially sensitive research and free will versus determinism debates in Issues and Debates, so cross-reference it there.",
      reforge:{stem:"Why is this a socially sensitive area of research?",options:{A:"The findings simply cannot be published in any scientific journals at all",B:"The research involves no human participants at all",C:"Biological research on offenders is prohibited by law",D:"Findings could justify screening and intervening before any offence"},correct:"D"}
    },
    {
      id:"FOR-22",stem:"Which statement best evaluates offender profiling as an investigative tool?",
      options:{A:"Profiling is useful for narrowing suspects but rarely identifies the offender",B:"Profiling has been abandoned by all police forces across the world",C:"Profiling reliably identifies the individual offender in most major investigations",D:"Profiling is equally applicable to every category of criminal offence"},correct:"A",tag:"MC-FOR-PROFILE",
      scaffold:"Copson's survey found 83% of officers considered profiling advice useful, but it led to identification of the offender in only 3% of cases — so its value lies in narrowing and prioritising a suspect pool rather than naming a culprit. High-profile failures matter for balance: the Rachel Nickell case, where an inaccurate profile drove a wrongful prosecution of Colin Stagg, shows the danger of over-reliance and confirmation bias. Bottom-up methods are generally better supported than top-down because they rest on statistical analysis rather than typologies from a small sample, and geographical profiling in particular has demonstrable practical value.",
      reforge:{stem:"What does the Rachel Nickell case illustrate about profiling?",options:{A:"Profiling always identifies the correct offender eventually",B:"Geographical profiling is more accurate than the top-down approach",C:"Profiling is only useful for crimes involving theft",D:"An inaccurate profile can drive a wrongful prosecution"},correct:"D"}
    },
    {
      id:"FOR-23",stem:"Twin and adoption studies of offending typically show that:",
      options:{A:"Concordance is identical for monozygotic and dizygotic twin pairs",B:"MZ concordance is higher than DZ, but well below one hundred per cent",C:"Adopted children resemble their adoptive parents far more than their biological ones",D:"There is no genetic component whatsoever to criminal offending"},correct:"B",tag:"MC-FOR-BIO",
      scaffold:"Christiansen's study of over 3,500 Danish twin pairs found concordance of about 35% for MZ and 13% for DZ males, and Crowe's adoption work found adopted children whose biological mother had a criminal record carried a substantially raised risk even when raised elsewhere. Together these indicate a genuine genetic contribution. But MZ concordance far below 100% is the decisive point: genes cannot be the whole story, so a diathesis-stress model fits better. Add the standard confound — MZ twins are usually raised in more similar environments than DZ twins, so shared environment is entangled with shared genes, and 'criminality' itself is a legal rather than biological category.",
      reforge:{stem:"Why is MZ concordance well below 100% theoretically important?",options:{A:"It proves that genes have no influence at all on offending",B:"It shows the twins cannot be genuinely monozygotic",C:"It demonstrates environmental factors must also contribute",D:"It means adoption studies are the only valid method"},correct:"C"}
    },
    {
      id:"FOR-24",stem:"Which overall conclusion about explanations of offending is best supported?",
      options:{A:"Biological factors alone provide an entirely complete account of all offending",B:"Offending is entirely a product of the social environment",C:"Only cognitive distortions can adequately explain criminal behaviour",D:"An interactionist account fits the evidence better than any single approach"},correct:"D",tag:"MC-FOR-COMPARE",
      scaffold:"No single explanation accounts for offending. Genetic evidence shows predisposition but MZ concordance well below 100%; Caspi's MAOA work shows the gene mattering only alongside maltreatment; differential association explains learning but not why siblings in the same environment diverge; cognitive distortions describe offenders' thinking without explaining its origin. A diathesis-stress or biosocial model integrates them: biological vulnerability, activated by adverse environment, mediated by learned attitudes and distorted cognition. This also has practical force, since effective interventions such as anger management and restorative justice target cognition and social relationships rather than biology. Argue for integration rather than picking a winner.",
      reforge:{stem:"Which finding best supports an interactionist explanation of offending?",options:{A:"MZ twin concordance rates will always reach exactly one hundred per cent in studies",B:"The MAOA variant predicts antisocial behaviour only alongside maltreatment",C:"Every convicted offender shows reduced prefrontal activity",D:"Offending occurs only among those with criminal peer groups"},correct:"B"}
    }
  ]
};

SUBJECTS["psych"].banks = ["PSY-SI","PSY-MEM","PSY-ATT","PSY-PATH","PSY-APP","PSY-BIO","PSY-RM","PSY-ID","PSY-COG","PSY-STR","PSY-FOR"];
SUBJECTS["psych"].sub = "AQA 7182 — current specification: Papers 1–3, 17 numbered content points";

// ===== A LEVEL HISTORY: AQA 7042 SELECTED CENTRE ROUTE =====
// The centre's route combines Wars and Welfare: Britain in Transition 1906–1957,
// The Making of a Superpower: USA 1865–1975, and a Tudor historical investigation.
const addAlevelHistoryBank = (bankId, label, spec, rawRows) => {
  const rows = rawRows.map(row => {
    const [term, definition, application] = row.split("|");
    return {term, definition, application};
  });
  BANKS[bankId] = {
    label,
    color: "#92400e",
    questions: rows.map((row, index) => {
      const next = rows[(index + 1) % rows.length];
      const previous = rows[(index + rows.length - 1) % rows.length];
      return {
        id:`${bankId}-${String(index + 1).padStart(2, "0")}`,
        spec,
        stem:`Which statement best explains ${row.term}?`,
        options:{
          A:row.definition,
          B:next.definition,
          C:previous.definition,
          D:`It had no meaningful effect on ${label.toLowerCase()}`
        },
        correct:"A",
        tag:`MC-${bankId}-${index + 1}`,
        scaffold:`${row.term}: ${row.definition}. In an A-level answer, connect the evidence to causation, change and continuity, significance, or the strength of a historical interpretation.`,
        reforge:{
          stem:`A historian is assessing ${row.term}. Which judgement is most accurate?`,
          options:{
            A:row.application,
            B:previous.application,
            C:next.application,
            D:`It cannot be tested using historical evidence`
          },
          correct:"A"
        }
      };
    })
  };
};

