// Remove the last legacy Sociology template from imported Paper 1 questions.
// This is deliberately applied at runtime so future bank extensions cannot
// reintroduce the same repeated "Which statement best describes..." cue.
const sociologyLegacyFrames = [
  term => `What is meant by ${term}?`,
  term => `Which example best illustrates ${term}?`,
  term => `How would a sociologist define ${term}?`,
  term => `A student encounters the term ${term}. What does it refer to?`,
  term => `Which description matches ${term}?`,
  term => `In sociological analysis, what does ${term} describe?`
];
const sociologyReforgeLegacyFrames = [
  term => `How could a sociologist apply ${term} to evidence?`,
  term => `Which scenario demonstrates ${term}?`,
  term => `A case study refers to ${term}. What does the reference mean?`,
  term => `Which conclusion follows from ${term}?`,
  term => `What would count as evidence of ${term}?`,
  term => `A related example tests ${term}. Which interpretation is most accurate?`
];
for (const bankId of SUBJECTS["soc"].banks) {
  for (const [index, question] of (BANKS[bankId]?.questions || []).entries()) {
    const match = String(question.stem || "").match(/^Which statement best describes (.+)\?$/i);
    if (match) question.stem = sociologyLegacyFrames[index % sociologyLegacyFrames.length](match[1]);
    const ref = question.reforge;
    const refMatch = String(ref?.stem || "").match(/^Which statement best describes (.+)\?$/i);
    if (refMatch) ref.stem = sociologyReforgeLegacyFrames[index % sociologyReforgeLegacyFrames.length](refMatch[1]);
  }
}

for (const subject of Object.values(SUBJECTS)) {
  for (const bankId of subject.banks || []) {
    for (const [index, question] of (BANKS[bankId]?.questions || []).entries()) {
      const ref = question.reforge;
      if (!ref || !/^Which statement best applies when this idea is used in a new business or examination scenario\?$/i.test(String(ref.stem || '').trim())) continue;
      ref.stem = genericReforgeFrames[index % genericReforgeFrames.length](stripGeneratedFrame(question.stem));
    }
  }
}

// Final pass: Reforge expansion can reintroduce a legacy prefix, so audit the
// fully assembled data one last time before it is exposed to the app.
for (const subject of Object.values(SUBJECTS)) {
  for (const bankId of subject.banks || []) {
    (BANKS[bankId]?.questions || []).forEach((question, index) => {
      diversifyLegacyStem(question, index);
      diversifyLegacyStem(question.reforge, index + 2);
    });
  }
}

// Last-mile student-facing cleanup: coverage variants and Reforge expansion
// run before this point, so apply the internal-label removal after all of them.
for (const subject of Object.values(SUBJECTS)) {
  for (const bankId of subject.banks || []) {
    for (const question of BANKS[bankId]?.questions || []) {
      removeInternalStemLabels(question);
      removeInternalStemLabels(question.reforge);
    }
  }
}

// Removing generation labels can reveal duplicate stems that were previously
// distinguished only by those labels. Keep the question standalone while
// marking later occurrences with a short, non-context-dependent suffix.
const duplicateStemSuffixes = [
  " (alternative exam formulation)",
  " (applied formulation)",
  " (comparison formulation)",
  " (second formulation)",
  " (exam practice variant)",
  " (another formulation)",
  " (revision variant)",
  " (alternative wording)"
];
for (const subject of Object.values(SUBJECTS)) {
  for (const bankId of subject.banks || []) {
    const seen = new Set();
    let duplicateIndex = 0;
    for (const question of BANKS[bankId]?.questions || []) {
      let normalized = String(question.stem || "").trim().toLowerCase();
      while (seen.has(normalized)) {
        question.stem = `${question.stem}${duplicateStemSuffixes[duplicateIndex % duplicateStemSuffixes.length]}`;
        duplicateIndex += 1;
        normalized = String(question.stem || "").trim().toLowerCase();
      }
      if (normalized) seen.add(normalized);
    }
  }
}

// Standalone-stem cleanup. These are generated presentation wrappers; they
// refer to an unstated prior question and are not useful to learners on their
// own. Remove them recursively while retaining the substantive question.
const generatedStemWrappers = [
  /^For comparison, consider:\s*/i,
  /^A related example tests (?:the same knowledge|this knowledge):\s*/i,
  /^Consider a related example:\s*/i,
  /^A separate scenario asks:\s*/i,
  /^In another worked example:\s*/i,
  /^The following case asks:\s*/i,
  /^Read this example carefully:\s*/i,
  /^A student applies the idea to a new example\.\s*/i,
  /^Which response fits this application\?\s*/i,
  /^A teacher changes the context but tests the same point\.\s*/i,
  /^A teacher tests the same principle in a fresh context\. Which answer is best\?\s*/i,
  /^In a fresh examination context,\s*/i,
  /^A revision question uses a new context\.\s*/i,
  /^Apply the concept to the following situation:\s*/i,
  /^Use the information in this scenario\.\s*/i,
  /^Read the example carefully before answering:\s*/i,
  /^Now consider this case:\s*/i,
  /^What follows in this particular case\?\s*/i,
  /^How should this related situation be interpreted\?\s*/i,
  /^Consider this case:\s*/i,
  /^A different case raises the same issue\.\s*/i,
  /^Which conclusion is supported by this example\?\s*/i,
  /^Which example best applies the idea\?\s*/i,
  /^A student must transfer the idea to a new case\.\s*/i,
  /^Which judgement is strongest in this context\?\s*/i,
  /^A teacher asks for a practical application\.\s*/i,
  /^What does the concept imply here\?\s*/i,
  /^Compare the idea with this example:\s*/i,
  /^Which statement is defensible when the context changes\?\s*/i,
  /^A new scenario tests the same principle\.\s*/i,
  /^A new example tests the same principle\. What should be concluded\?\s*/i,
  /^A teacher tests the same principle in a fresh context\. Which answer is best\?\s*/i,
  /^What would the idea predict in a fresh example\?\s*/i,
  /^A new context presents the question:\s*/i,
  /^What is the most accurate application\?\s*/i,
  /^Use the case to identify the best answer:\s*/i,
  /^Which interpretation follows from this example\?\s*/i,
  /^Which response shows understanding when the context changes\?\s*/i,
  /^Transfer the principle to this unfamiliar case\.\s*/i,
  /^Apply the underlying idea to a new scenario\.\s*/i
];
const removeGeneratedStemWrappers = item => {
  if (!item?.stem) return "";
  let stem = String(item.stem).trim();
  const relatedInterpretation = stem.match(/^A related example tests (.+?)\.\s*Which interpretation is most accurate\?$/i);
  if (relatedInterpretation) stem = `Which interpretation of ${relatedInterpretation[1]} is most accurate?`;
  let changed = true;
  while (changed) {
    changed = false;
    for (const wrapper of generatedStemWrappers) {
      const next = stem.replace(wrapper, "").trim();
      if (next !== stem) { stem = next; changed = true; }
    }
  }
  item.stem = stem;
  return stem;
};
for (const subject of Object.values(SUBJECTS)) {
  for (const bankId of subject.banks || []) {
    for (const question of BANKS[bankId]?.questions || []) {
      const baseStem = removeGeneratedStemWrappers(question);
      const ref = question.reforge;
      if (ref && /Which statement best applies when this idea is used in a new business or examination scenario\?/i.test(String(ref.stem || ""))) {
        ref.stem = baseStem;
      } else {
        removeGeneratedStemWrappers(ref);
      }
      if (ref && ref.options && !String(ref.stem || "").trim()) {
        ref.stem = baseStem;
      }
    }
  }
}

// Preserve the exact Component 2.5 mapping after the broader legacy mapping
// passes above have finished.
for (const question of BANKS["CS-2"]?.questions || []) {
  if (String(question.id || "").startsWith("CS-ETH-")) {
    question.specPointId = "eduqas-a-cs-2.5";
    question.spec = "CS-2.5";
  }
}

// Edexcel A-level Mathematics gaps: targeted application questions for
// coordinate geometry, numerical methods, vectors and mechanics.
const mathsSpecQuestions = [
  ["MATH-COV-01", "MATH-1", "edexcel-a-maths-2.2", "The line through (2, 5) and (6, 13) has gradient:", {A:"2",B:"1/2",C:"3",D:"4"}, "A", "Gradient is (13 − 5)/(6 − 2) = 2."],
  ["MATH-COV-02", "MATH-1", "edexcel-a-maths-2.2", "The circle x² + y² − 6x + 4y − 12 = 0 has centre:", {A:"(−3, 2)",B:"(3, −2)",C:"(6, −4)",D:"(−6, 4)"}, "B", "Completing the square gives (x − 3)² + (y + 2)² = 25."],
  ["MATH-COV-03", "MATH-1", "edexcel-a-maths-2.8", "Newton–Raphson applied to f(x) = x² − 5 gives the iteration:", {A:"xₙ₊₁ = ½(xₙ + 5/xₙ)",B:"xₙ₊₁ = xₙ² − 5",C:"xₙ₊₁ = 5 − xₙ²",D:"xₙ₊₁ = xₙ + (xₙ² − 5)"}, "A", "Using xₙ₊₁ = xₙ − f(xₙ)/f′(xₙ) gives ½(xₙ + 5/xₙ)."],
  ["MATH-COV-04", "MATH-1", "edexcel-a-maths-2.8", "Using the trapezium rule with width 1 and ordinates 1, 2 and 4 gives:", {A:"3.5",B:"4",C:"4.5",D:"5"}, "C", "The estimate is ½[1 + 2(2) + 4] = 4.5."],
  ["MATH-COV-05", "MATH-1", "edexcel-a-maths-2.9", "The magnitude of the vector (3, −4) is:", {A:"1",B:"4",C:"5",D:"7"}, "C", "The magnitude is √(3² + 4²) = 5."],
  ["MATH-COV-06", "MATH-1", "edexcel-a-maths-2.9", "The vector (6, −3) is what multiple of (2, −1)?", {A:"2",B:"3",C:"−3",D:"6"}, "B", "Both components are multiplied by 3."],
  ["MATH-COV-07", "MATH-3", "edexcel-a-maths-4.2", "A particle has u = 3 m s⁻¹ and a = 2 m s⁻² for 4 seconds. Its final velocity is:", {A:"5 m s⁻¹",B:"8 m s⁻¹",C:"10 m s⁻¹",D:"11 m s⁻¹"}, "D", "v = u + at = 3 + 2(4) = 11 m s⁻¹."],
  ["MATH-COV-08", "MATH-3", "edexcel-a-maths-4.2", "A particle has u = 5 m s⁻¹, a = −1 m s⁻² and t = 3 s. Its displacement is:", {A:"10.5 m",B:"12 m",C:"13.5 m",D:"15 m"}, "A", "s = ut + ½at² = 15 − 4.5 = 10.5 m."],
  ["MATH-COV-09", "MATH-3", "edexcel-a-maths-4.3", "A 5 N resultant force acts on a 2 kg particle. Its acceleration is:", {A:"0.4 m s⁻²",B:"2.5 m s⁻²",C:"7 m s⁻²",D:"10 m s⁻²"}, "B", "Newton's second law gives a = F/m = 2.5 m s⁻²."],
  ["MATH-COV-10", "MATH-3", "edexcel-a-maths-4.3", "At terminal velocity, the resultant force on a falling object is:", {A:"Equal to its weight downward",B:"Equal to its drag upward",C:"Zero",D:"Increasing"}, "C", "Drag balances weight, so the resultant force is zero."],
  ["MATH-COV-11", "MATH-3", "edexcel-a-maths-4.4", "A 20 N force acts perpendicular to a pivot at 0.4 m. Its moment is:", {A:"5 N m",B:"8 N m",C:"20.4 N m",D:"50 N m"}, "B", "Moment = force × perpendicular distance = 8 N m."],
  ["MATH-COV-12", "MATH-3", "edexcel-a-maths-4.4", "A clockwise moment of 12 N m is balanced by:", {A:"6 N m anticlockwise",B:"Zero moment",C:"12 N m clockwise",D:"12 N m anticlockwise"}, "D", "Rotational equilibrium requires equal opposite moments."],
  ["MATH-COV-13", "MATH-3", "edexcel-a-maths-4.5", "The resultant of perpendicular vectors of magnitudes 3 and 4 has magnitude:", {A:"1",B:"5",C:"7",D:"12"}, "B", "The magnitude is √(3² + 4²) = 5."],
  ["MATH-COV-14", "MATH-3", "edexcel-a-maths-4.5", "A vector in the direction (6, 8) has unit vector:", {A:"(3/5, 4/5)",B:"(6, 8)",C:"(6/14, 8/14)",D:"(4/3, 5/3)"}, "A", "The vector has magnitude 10, so divide both components by 10."]
];
for (const [id, bankId, specPointId, stem, options, correct, scaffold] of mathsSpecQuestions) {
  BANKS[bankId].questions.push({id, stem, options, correct, tag:"MC-MATH-SPEC", scaffold, specPointId, spec:specPointId});
}

// Final language pass: a few later-added coverage questions were introduced
// after the main stem-diversity migration. Rephrase those remaining generic
// "Which statement/claim" openings so the visible bank does not teach a
// test-taking shortcut.
const finalStemLanguagePass = (item, index) => {
  if (!item?.stem) return;
  let stem = String(item.stem).trim()
    .replace(/\s*\((?:comparison formulation|second formulation|exam practice variant|alternative wording|another formulation|applied formulation)(?:\s*\([^)]*\))?\)\s*$/i, "")
    .trim();
  const replacements = [
    [/^which statement correctly explains why amines are basic\?$/i, "Why are amines basic?"],
    [/^which statement correctly describes the difference between discontinuous and continuous variation\?$/i, "How do discontinuous and continuous variation differ?"],
    [/^which statement best describes the concept of ['\"]media convergence['\"]\??$/i, "How should media convergence be understood?"],
    [/^which (?:statement|claim) about the Spanish political system is most accurate for A Level study\??$/i, "How is the Spanish political system organised for A Level study?"],
    [/^which statement describes conservation of energy\?$/i, "How is energy conserved?"],
  ];
  for (const [pattern, replacement] of replacements) {
    if (pattern.test(stem)) { item.stem = replacement; return; }
  }
  if (/^which statement\b/i.test(stem)) item.stem = stem.replace(/^which statement\b/i, "Which option");
  else if (/^which claim\b/i.test(stem)) item.stem = stem.replace(/^which claim\b/i, "Which option");
};
for (const subject of Object.values(SUBJECTS)) {
  for (const bankId of subject.banks || []) {
    for (const [index, question] of (BANKS[bankId]?.questions || []).entries()) {
      finalStemLanguagePass(question, index);
      finalStemLanguagePass(question.reforge, index + 2);
    }
  }
}

// The standalone cleanup can make previously different wrappers identical.
// Re-run the lightweight duplicate guard after the wrappers are removed.
for (const subject of Object.values(SUBJECTS)) {
  for (const bankId of subject.banks || []) {
    const seen = new Set();
    let duplicateIndex = 0;
    for (const question of BANKS[bankId]?.questions || []) {
      let normalized = String(question.stem || "").trim().toLowerCase();
      while (seen.has(normalized)) {
        question.stem = `${question.stem}${duplicateStemSuffixes[duplicateIndex % duplicateStemSuffixes.length]}`;
        duplicateIndex += 1;
        normalized = String(question.stem || "").trim().toLowerCase();
      }
      if (normalized) seen.add(normalized);
    }
  }
}
